(16, 53, 'Gây cấn', 'gay-can', 'Phim căng thẳng, hồi hộp với tình tiết bất ngờ.', NULL, '2026-05-26 10:30:53', '2026-05-26 10:30:53', NULL),
(17, 10752, 'Chiến tranh', 'chien-tranh', 'Phim lấy bối cảnh chiến trường và xung đột vũ trang.', NULL, '2026-05-26 10:30:53', '2026-05-26 10:30:53', NULL);
