INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `original_title`, `slug`, `tagline`, `synopsis`, `poster`, `backdrop`, `trailer_url`, `release_date`, `runtime`, `country`, `language`, `budget`, `revenue`, `tmdb_vote_average`, `tmdb_vote_count`, `tmdb_popularity`, `avg_rating`, `rating_count`, `view_count`, `is_approved`, `status`, `is_featured`, `featured_order`, `created_by_user_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 1304313, 'Một bộ phim của Lee Cronin: Xác ướp', 'Lee Cronin\'s The Mummy', 'mot-bo-phim-cua-lee-cronin-xac-uop-2026', NULL, 'Con gái nhỏ của một nhà báo biến mất không dấu vết giữa sa mạc. Tám năm sau, gia đình tan vỡ của họ bàng hoàng khi cô bé bất ngờ được đưa trở về — nhưng cuộc đoàn tụ tưởng chừng hạnh phúc nhanh chóng biến thành một cơn ác mộng sống.', 'https://image.tmdb.org/t/p/w500/fIbu9GsLv7j8uWA8OiAEtpNEDsZ.jpg', 'https://image.tmdb.org/t/p/w1280/wMrV8SLne1jHLeYS0lLrA1Tf86P.jpg', NULL, '2026-04-15', NULL, NULL, NULL, NULL, NULL, 8.00, 1199, 802.337, 7.4, 30, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(2, 1380291, 'Siêu Điệp Viên Jack Ryan: Bóng Ma Chiến Tranh', 'Tom Clancy\'s Jack Ryan: Ghost War', 'sieu-diep-vien-jack-ryan-bong-ma-chien-tranh-2026', NULL, 'Khi một nhiệm vụ bí mật quốc tế làm sáng tỏ một âm mưu chết người, Ryan buộc phải quay trở lại thế giới gián điệp để đối đầu với một đơn vị hoạt động đen tối lừa đảo.', 'https://image.tmdb.org/t/p/w500/8ehYxUh5MWE41AeE9gkHE8DKzvB.jpg', 'https://image.tmdb.org/t/p/w1280/dd31qJxOarrHyGZwYsCzOjobQzP.jpg', NULL, '2026-05-20', NULL, NULL, NULL, NULL, NULL, 7.24, 288, 525.208, 7.9, 15, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(3, 1226863, 'Phim Super Mario Thiên Hà', 'The Super Mario Galaxy Movie', 'phim-super-mario-thien-ha-2026', NULL, 'Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là \"mẹ\" của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực siêu thực và hình ảnh rực rỡ.', 'https://image.tmdb.org/t/p/w500/h1FlxHYiVcZVkIE5XW599ZkV6Sr.jpg', 'https://image.tmdb.org/t/p/w1280/9Z2uDYXqJrlmePznQQJhL6d92Rq.jpg', NULL, '2026-04-01', NULL, NULL, NULL, NULL, NULL, 7.98, 1887, 387.086, 7.1, 12, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(4, 687163, 'Thoát Khỏi Tận Thế', 'Project Hail Mary', 'thoat-khoi-tan-the-2026', NULL, 'Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.', 'https://image.tmdb.org/t/p/w500/7NzV9SN5ocWzMrdQw9fFDgLYVJC.jpg', 'https://image.tmdb.org/t/p/w1280/2I1OFQJ0L9T0dpU6FobKFWV2PxX.jpg', NULL, '2026-03-15', NULL, NULL, NULL, NULL, NULL, 8.63, 4110, 402.524, 7.5, 9, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(5, 1339713, 'Điều Ước Cuồng Yêu', 'Obsession', 'dieu-uoc-cuong-yeu-2026', NULL, 'Sau khi phá vỡ “Cây Liễu Một Điều Ước” bí ẩn để chinh phục trái tim người mình thầm yêu, một chàng trai lãng mạn tuyệt vọng nhận được đúng thứ mình mong muốn. Nhưng rất nhanh, anh phát hiện ra rằng không phải mọi ước muốn đều vô hại — và một số khát khao luôn phải trả giá bằng những hệ quả đen tối, rùng rợn.', 'https://image.tmdb.org/t/p/w500/7uTShFX1Xv1AODdRveMwVp1DQ99.jpg', 'https://image.tmdb.org/t/p/w1280/rZfmzpixLKLR3Hg2u0WgC7XLFl8.jpg', NULL, '2026-04-16', NULL, NULL, NULL, NULL, NULL, 7.90, 275, 334.775, 5.7, 10, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(6, 1007757, 'Cuộc phiêu lưu biến hóa', 'Swapped', 'cuoc-phieu-luu-bien-hoa-2026', NULL, 'Một sinh vật nhỏ bé trong rừng và một chú chim oai vệ bất ngờ hoán đổi thân xác, buộc chúng phải hợp sức để sống sót trong chuyến phiêu lưu náo loạn nhất đời mình.', 'https://image.tmdb.org/t/p/w500/tHhxWxge06goXU6ZQH1hj7vK8Hd.jpg', 'https://image.tmdb.org/t/p/w1280/zMwhWailP1WY7sb6AoE6b8ugoy.jpg', NULL, '2026-05-01', NULL, NULL, NULL, NULL, NULL, 8.97, 1385, 328.702, 7.1, 13, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(7, 350, 'Yêu Nữ Thích Hàng Hiệu', 'The Devil Wears Prada', 'yeu-nu-thich-hang-hieu-2006', NULL, 'Một sinh viên tốt nghiệp thông minh nhưng nhạy cảm mới làm nghề trợ lý cho Miranda Priestly, tổng biên tập tạp chí thời trang cao cấp. Liệu cô ấy có thể hoàn thành công việc cho Miranda khó tính không?', 'https://image.tmdb.org/t/p/w500/d4nV102c3QLA5T77tjfq9tcCvmi.jpg', 'https://image.tmdb.org/t/p/w1280/gkh6Nt8DtY1XT4gQsyFq9XAVJlJ.jpg', NULL, '2006-06-29', NULL, NULL, NULL, NULL, NULL, 7.42, 13553, 201.211, 8.2, 12, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(8, 931285, 'Cuộc Chiến Sinh Tử II', 'Mortal Kombat II', 'cuoc-chien-sinh-tu-ii-2026', NULL, 'Những chiến binh được yêu thích nhất — nay có thêm sự góp mặt của Johnny Cage — buộc phải đối đầu lẫn nhau trong trận chiến tối thượng đẫm máu và không khoan nhượng. Mục tiêu: đánh bại sự thống trị tàn bạo của Shao Kahn, kẻ đang đe dọa sự tồn vong của Địa Giới và tất cả những ai đứng lên bảo vệ nó.', 'https://image.tmdb.org/t/p/w500/f9tWGssOpViDbh6dV6gtLFiCc7i.jpg', 'https://image.tmdb.org/t/p/w1280/4EAAwpylq313qrDqpCxulUrXBNF.jpg', NULL, '2026-05-06', NULL, NULL, NULL, NULL, NULL, 6.80, 301, 219.207, 7.6, 14, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(9, 460465, 'Mortal Kombat: Cuộc Chiến Sinh Tử', 'Mortal Kombat', 'mortal-kombat-cuoc-chien-sinh-tu-2021', NULL, 'Mortal Kombat: Cuộc Chiến Sinh Tử xoay quanh võ sĩ võ thuật tổng hợp Cole Young (Lewis Tan), người mang trên mình một vết chàm rồng đen bí ẩn - biểu tượng của Mortal Kombat. Cole Young không hề biết về dòng máu bí ẩn đang chảy trong người anh, hay vì sao anh lại bị tên sát thủ Sub-Zero (Joe Taslim) săn lùng. Vì sự an nguy của gia đình, Cole cùng với một nhóm những chiến binh đã được tuyển chọn để tham gia vào một trận chiến đẫm máu nhằm chống lại những kẻ thù đến từ Outworld.', 'https://image.tmdb.org/t/p/w500/5iHZ6KUSnLEnStXJ6BfFA5Uk2PT.jpg', 'https://image.tmdb.org/t/p/w1280/6ELCZlTA5lGUops70hKdB83WJxH.jpg', NULL, '2021-04-07', NULL, NULL, NULL, NULL, NULL, 7.03, 6628, 184.363, 5.4, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(10, 1228710, 'Star Wars: Mandalorian và Grogu', 'The Mandalorian and Grogu', 'star-wars-mandalorian-va-grogu-2026', NULL, 'Đế Chế tàn bạo đã sụp đổ, nhưng những lãnh chúa chiến tranh của phe Đế Chế vẫn còn rải rác khắp thiên hà. Khi Nền Cộng hòa Mới nỗ lực bảo vệ những gì Quân Nổi Loạn đã chiến đấu để giành lấy, họ đã nhờ đến sự trợ giúp của thợ săn tiền thưởng Mandalorian - huyền thoại Din Djarin và cậu bé học việc Grogu.', 'https://image.tmdb.org/t/p/w500/554NefDjiPZ4ssHyWl3LiqlQZBT.jpg', 'https://image.tmdb.org/t/p/w1280/7OedxK0BvSKJ0ZWCPRYADViTBx6.jpg', NULL, '2026-05-20', NULL, NULL, NULL, NULL, NULL, 6.75, 231, 192.049, 6.4, 8, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(11, 1318447, 'Săn Mạng', 'Apex', 'san-mang-2026', NULL, 'Đang đau buồn, người phụ nữ nọ thử thách giới hạn trong chuyến phiêu lưu đơn độc giữa vùng hoang dã Úc, nhưng lại bị cuốn vào trò chơi méo mó của một kẻ sát nhân coi cô là con mồi.', 'https://image.tmdb.org/t/p/w500/jMSlZZScFPA6YqatxzrixoMlTDk.jpg', 'https://image.tmdb.org/t/p/w1280/oTE4lNs4PSG5iIWjqaTdCIFJ4Bs.jpg', NULL, '2026-04-24', NULL, NULL, NULL, NULL, NULL, 6.69, 1229, 174.206, 7.6, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(12, 83533, 'Avatar: Lửa và Tro Tàn', 'Avatar: Fire and Ash', 'avatar-lua-va-tro-tan-2025', NULL, 'Sau cuộc chiến tàn khốc với RDA và nỗi mất mát to lớn khi đứa con trai cả hy sinh, Jake Sully và Neytiri phải đối mặt với một mối đe dọa mới trên Pandora: tộc Tro Tàn — một nhóm Na\'vi hung bạo và khát khao quyền lực, do thủ lĩnh tàn nhẫn Varang dẫn dắt. Gia đình Jake buộc phải chiến đấu để sinh tồn và bảo vệ tương lai của Pandora, trong một cuộc xung đột đẩy họ đến giới hạn cuối cùng cả về thể xác lẫn tinh thần.', 'https://image.tmdb.org/t/p/w500/w6DBmG260sCHBQdGzkBIVn9gAQZ.jpg', 'https://image.tmdb.org/t/p/w1280/iN41Ccw4DctL8npfmYg1j5Tr1eb.jpg', NULL, '2025-12-17', NULL, NULL, NULL, NULL, NULL, 7.50, 3187, 159.635, 8.1, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(13, 1419406, 'Bổ Phong Truy Ảnh', '捕风追影', 'bo-phong-truy-anh-2025', NULL, 'Wong Tak-Chung, một cựu chuyên gia giám sát được biết đến với khả năng phân tích dữ liệu và truy vết bậc thầy, bị cảnh sát Ma Cao mời trở lại hợp tác điều tra sau khi xuất hiện hàng loạt vụ cướp quy mô lớn do một tổ chức tội phạm công nghệ cao thực hiện.', 'https://image.tmdb.org/t/p/w500/5LGUvRBXoXHsMZsZrCGBOVmwOVd.jpg', 'https://image.tmdb.org/t/p/w1280/4BtL2vvEufDXDP4u6xQjjQ1Y2aT.jpg', NULL, '2025-08-16', NULL, NULL, NULL, NULL, NULL, 7.37, 683, 149.377, 7.5, 10, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(14, 936075, 'Michael', 'Michael', 'michael-2026', NULL, 'Michael là bức chân dung điện ảnh khắc họa cuộc đời và di sản của một trong những nghệ sĩ có sức ảnh hưởng lớn nhất mà thế giới từng biết đến. Bộ phim kể về cuộc đời của Michael Jackson ngoài âm nhạc, theo dấu hành trình từ khi tài năng phi thường của ông được phát hiện trong vai trò giọng ca chính của nhóm Jackson Five, cho đến khi ông trở thành một nghệ sĩ có tầm nhìn xa, với khát vọng sáng tạo không ngừng để vươn tới danh hiệu “ngôi sao giải trí vĩ đại nhất thế giới”. Cho thấy cuộc sống phía sau hào quang sân khấu lẫn những màn trình diễn mang tính biểu tượng nhất trong giai đoạn đầu sự nghiệp solo, bộ phim mang đến cho khán giả một góc nhìn chân thực hơn bao giờ hết về Michael Jackson. Đây chính là nơi câu chuyện của ông bắt đầu.', 'https://image.tmdb.org/t/p/w500/sXP7VzpnHQIThf5v6b64XaczEK2.jpg', 'https://image.tmdb.org/t/p/w1280/xBT0oNq6rsTFv4SxG5uGRIEOrq6.jpg', NULL, '2026-04-22', NULL, NULL, NULL, NULL, NULL, 7.59, 844, 130.912, 6.9, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(15, 1327819, 'Hoppers: Cú Nhảy Kỳ Diệu', 'Hoppers', 'hoppers-cu-nhay-ky-dieu-2026', NULL, 'Các nhà khoa học đã khám phá ra cách \"nhảy\" ý thức con người vào những con vật robot sống động như thật, cho phép con người giao tiếp với động vật dưới hình dạng động vật! Nhờ công nghệ mới này, Mabel sẽ khám phá những bí ẩn trong thế giới động vật vượt xa mọi điều cô từng tưởng tượng.', 'https://image.tmdb.org/t/p/w500/1A7WxXAYddDCrO9dTCEdSzQKU9d.jpg', 'https://image.tmdb.org/t/p/w1280/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg', NULL, '2026-03-04', NULL, NULL, NULL, NULL, NULL, 8.12, 1230, 134.798, 7.4, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(16, 1628367, 'Nghĩa Vụ', 'कर्त्तव्य', 'nghia-vu-2026', NULL, 'Khi gia đình bị đẩy vào nguy hiểm và những mối đe dọa đáng sợ đang cận kề, một sĩ quan cảnh sát buộc phải quyết định anh sẵn sàng đi đến đâu để giữ trọn bổn phận.', 'https://image.tmdb.org/t/p/w500/doTwMyAphlDL5Z8WqE3elWWvj8M.jpg', 'https://image.tmdb.org/t/p/w1280/mHm73HhpvGWfRkXNErcwc15Czrv.jpg', NULL, '2026-05-15', NULL, NULL, NULL, NULL, NULL, 6.25, 12, 124.824, 7.1, 11, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(17, 1297842, 'Tuyển Thủ Dê: \"Mùi\" Vị Chiến Thắng', 'GOAT', 'tuyen-thu-de-mui-vi-chien-thang-2026', NULL, 'Will là một chú dê nhỏ với những ước mơ lớn, người có được cơ hội duy nhất trong đời để gia nhập các vận động viên chuyên nghiệp và thi đấu môn rugebol — một môn thể thao cường độ cao, pha trộn và đối kháng toàn diện, nơi các loài động vật nhanh nhất và hung dữ nhất thế giới thống trị. Những đồng đội mới của Will không mấy hào hứng khi có một chú dê nhỏ trong đội hình, nhưng Will quyết tâm tạo nên một cuộc cách mạng cho môn thể thao này và chứng minh một lần và mãi mãi rằng: “Nhỏ bé cũng biết chơi!”', 'https://image.tmdb.org/t/p/w500/wZRJ3Q2XRJHov1SS80sTXbfjkz9.jpg', 'https://image.tmdb.org/t/p/w1280/tq3h43fZy0H80vzf47MAY7R9Mxo.jpg', NULL, '2026-02-11', NULL, NULL, NULL, NULL, NULL, 8.11, 677, 124.378, 8.9, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(18, 1311031, 'Thanh Gươm Diệt Quỷ: Vô Hạn Thành', '劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来', 'thanh-guom-diet-quy-vo-han-thanh-2025', NULL, 'Khi các thành viên của Sát Quỷ Đoàn và Trụ Cột tham gia vào chương trình đặc huấn để chuẩn bị cho trận chiến sắp với lũ quỷ, Kibutsuji Muzan xuất hiện tại Dinh thự Ubuyashiki. Khi thủ lĩnh của Sát Quỷ Đoàn gặp nguy hiểm, Tanjiro và các Trụ Cột trở về trụ sở Thế nhưng, Muzan bất ngờ kéo toàn bộ Sát Quỷ Đoàn đến hang ổ cuối cùng của lũ quỷ là Vô Hạn Thành, mở màn cho trận đánh cuối cùng của cả hai phe.', 'https://image.tmdb.org/t/p/w500/nV99ACeAa8fFFso0tQZ3HktEf5X.jpg', 'https://image.tmdb.org/t/p/w1280/1RgPyOhN4DRs225BGTlHJqCudII.jpg', NULL, '2025-07-18', NULL, NULL, NULL, NULL, NULL, 7.72, 840, 125.580, 8.5, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(19, 1196067, 'Kẻ Phá Vỡ Thế Giới', 'Worldbreaker', 'ke-pha-vo-the-gioi-2025', NULL, 'Năm năm trước, một vết nứt trong kết cấu thực tại đã mở ra cánh cổng đưa những sinh vật từ chiều không gian khác tràn vào thế giới của chúng ta với mục đích hủy diệt. Để bảo vệ con gái, một người cha đưa cô bé ẩn náu trên một hòn đảo biệt lập, vừa che chở vừa rèn luyện cô cho cuộc sống sinh tồn và những trận chiến sắp tới. Nhưng khi thế giới đứng bên bờ sụp đổ, không còn nơi nào thực sự an toàn.', 'https://image.tmdb.org/t/p/w500/ahj1JU8r0uJv7QII5Uj7tKzbEsC.jpg', 'https://image.tmdb.org/t/p/w1280/gMItMzDOyrfQGZsMWRM9tdxq5cV.jpg', NULL, '2025-10-30', NULL, NULL, NULL, NULL, NULL, 5.89, 173, 117.447, 7.8, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(20, 249397, 'Người Đàn Bà Cuồng Dâm: Phần 2', 'Nymphomaniac: Vol. II', 'nguoi-dan-ba-cuong-dam-phan-2-2013', NULL, 'Người Đàn Bà Cuồng Dâm 2 tiếp tục kể về cuộc đời của Joe. Joe sống với Jerôme và Marcel (con trai của họ) trong bình yên, cô mất cảm hứng với tình dục. Joe đi tìm sự điên loạn, trụy lạc và bạo dâm mong cảm hứng tình dục quay trở lại với mình. Jerôme dắt Marcel bỏ đi và đưa con trai mình đến làm con nuối của 1 gia đình khác. Sau này, Joe được gửi đến bác sĩ phụ khoa của cô để điều trị, nhưng cô không thừa nhận rằng cô đang nghiện tình dục. Trong khi đó Seligman nói với Joe rằng ông vẫn còn “zin” và giúp cô hiểu hành động của mình.', 'https://image.tmdb.org/t/p/w500/iLUNqgNKuWn667kXCKztSxYbT3k.jpg', 'https://image.tmdb.org/t/p/w1280/oQEAWIr3thvSICvoQnFEqyuf0Oz.jpg', NULL, '2013-12-25', NULL, NULL, NULL, NULL, NULL, 6.71, 3158, 114.729, 7.9, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(21, 564, 'Xác Ướp 1', 'The Mummy', 'xac-uop-1-1999', NULL, 'Một nhóm nhà khảo cổ dẫn đầu là O’Connell tiến hành cuộc hành trình tới xứ sở của kim tự tháp. Họ có tham vọng khám phá bí mật của xác ướp thầy tu Imhotep, nhưng vô tình đem lại cơ hội hồi sinh cho hắn, khiến cuộc chiến sinh tồn nổ ra.  Bộ ba Rick – Evelyn – Jonathan rời Cairo xuôi theo dòng dông Nile, ngang qua sa mạc Sahara và họ bắt đầu nhận ra sự khắc nghiệt của thiên nhiên không là gì so với những thế lượng đen tối họ phải đối đầu. Đó là những kẻ tham lam vô độ không ngại gì sự huyền bí của Ai Cập tới kiếm tìm châu báu và sự tấn công của xác ướp hồi sinh Imhotep cùng nhân tình của hắn Anck-su-namun vì để hồi sinh cho người tình, Imhotep cần máu và cơ thể của Evelyn.  Mối nguy hiểm không chỉ đến với những kẻ săn kho báu và đoàn khảo cổ của Rick mà nó đã trở thành sự đe dọa cho toàn thế giới khi Imhotep âm mưu gây dựng lại đế chế độc tài Ai Cập cổ xưa bằng phép thuật của một thầy tu quyền năng.', 'https://image.tmdb.org/t/p/w500/rzbRuZDEER9UpRzL946PiHtq1tY.jpg', 'https://image.tmdb.org/t/p/w1280/8zLS8p1tRyWFLRFfmgQq0j5WE6z.jpg', NULL, '1999-04-16', NULL, NULL, NULL, NULL, NULL, 6.97, 9993, 94.447, 7.9, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(22, 1330021, 'Kỷ vật vô giá', 'Remarkably Bright Creatures', 'ky-vat-vo-gia-2026', NULL, 'Khi làm ca đêm tại thủy cung ở thị trấn nhỏ, góa phụ kết bạn với một con bạch tuộc thông minh và một chàng trai lang bạt. Bộ phim chính kịch cảm động chuyển thể từ sách bán chạy.', 'https://image.tmdb.org/t/p/w500/9HcEqn3D4J6b2Z0jK54id9nA0fr.jpg', 'https://image.tmdb.org/t/p/w1280/bVGHSe47W6oCQL1Q88pvRAet51A.jpg', NULL, '2026-05-07', NULL, NULL, NULL, NULL, NULL, 8.52, 426, 95.969, 5.2, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(23, 1630423, 'Sát Thủ Yêu Dấu', 'เลือดรัก นักฆ่า', 'sat-thu-yeu-dau-2026', NULL, 'Trở thành mục tiêu vì nhóm máu hiếm, người phụ nữ tìm thấy sự che chở trong vòng tay gã sát thủ nguy hiểm cô yêu. Cùng nhau, họ chiến đấu để sinh tồn.', 'https://image.tmdb.org/t/p/w500/b1VNnA0ewb6F0hccCpPpXD8c8oT.jpg', 'https://image.tmdb.org/t/p/w1280/xA6AM5MvEkieZKlv1Tn3sN23I7i.jpg', NULL, '2026-05-06', NULL, NULL, NULL, NULL, NULL, 8.64, 207, 93.446, 7.8, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(24, 1301421, 'Đội Thám Tử Cừu: Án Mạng Lúc Nửa Đêm', 'The Sheep Detectives', 'doi-tham-tu-cuu-an-mang-luc-nua-dem-2026', NULL, 'Trong bộ phim trinh thám hài hước, độc đáo này, George (Hugh Jackman) là một người chăn cừu, mỗi tối đều đọc tiểu thuyết trinh thám cho đàn cừu yêu quý nghe, nghĩ rằng chúng không thể hiểu được. Nhưng khi George bất ngờ qua đời trong một sự cố bí ẩn trên trang trại, đàn cừu quyết định tự mình trở thành thám tử. Lần theo manh mối và điều tra các nghi phạm là con người, chúng chứng minh rằng ngay cả cừu cũng có thể phá án xuất sắc.', 'https://image.tmdb.org/t/p/w500/fEpV3vWBQ1eZefIIcwaiTduXEEP.jpg', 'https://image.tmdb.org/t/p/w1280/a8uQvrplTkhGJQog6GZ6CqF8An6.jpg', NULL, '2026-04-30', NULL, NULL, NULL, NULL, NULL, 7.60, 106, 85.189, 6.9, 10, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(25, 1266127, 'Trò Chơi Của Quỷ 2', 'Ready or Not: Here I Come', 'tro-choi-cua-quy-2-2026', NULL, 'Chỉ ít phút sau khi sống sót khỏi cuộc tấn công toàn diện của gia tộc Le Domas, Grace nhận ra mình đã bước sang cấp độ tiếp theo của trò chơi ác mộng — lần này, với người chị em xa cách Faith đứng bên cạnh. Grace chỉ có một cơ hội để sống sót, bảo vệ em gái, và giành lấy Ngai Cao của Hội Đồng — thế lực đang kiểm soát cả thế giới. Bốn gia tộc đối địch đang truy lùng cô để đoạt lấy ngai vàng, và kẻ chiến thắng sẽ thống trị tất cả.', 'https://image.tmdb.org/t/p/w500/9eWzfMfdd9JHDhPqKdNB9Y08T6B.jpg', 'https://image.tmdb.org/t/p/w1280/9dMp9t0d0nIGhiil8TyqChwiNwA.jpg', NULL, '2026-03-19', NULL, NULL, NULL, NULL, NULL, 7.69, 861, 92.315, 6.5, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(26, 1084242, 'Phi Vụ Động Trời 2', 'Zootopia 2', 'phi-vu-dong-troi-2-2025', NULL, 'Trong bộ phim \"Zootopia 2 - Phi Vụ Động Trời 2\" từ Walt Disney Animation Studios, hai thám tử Judy Hopps (lồng tiếng bởi Ginnifer Goodwin) và Nick Wilde (lồng tiếng bởi Jason Bateman) bước vào hành trình truy tìm một sinh vật bò sát bí ẩn vừa xuất hiện tại Zootopia và khiến cả vương quốc động vật bị đảo lộn. Để phá được vụ án, Judy và Nick buộc phải hoạt động bí mật tại những khu vực mới lạ của thành phố – nơi mối quan hệ đồng nghiệp của họ bị thử thách hơn bao giờ hết.', 'https://image.tmdb.org/t/p/w500/5wXpOF9WPUKliIzNBdAqwAStLHU.jpg', 'https://image.tmdb.org/t/p/w1280/lgotja3xMoJZbynwHfcQcJAEMWH.jpg', NULL, '2025-11-26', NULL, NULL, NULL, NULL, NULL, 7.60, 2806, 85.414, 10.0, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(27, 744275, 'Từ Khi Chúng Ta Tan Vỡ', 'After We Fell', 'tu-khi-chung-ta-tan-vo-2021', NULL, 'Tessa và Hardin yêu nhau hơn bao giờ hết. Nhưng trước những bí mật còn giấu kín và lời hứa còn dang dở, chỉ tình yêu thôi thì chưa đủ để cùng xây đắp tương lai.', 'https://image.tmdb.org/t/p/w500/dU4HfnTEJDf9KvxGS9hgO7BVeju.jpg', 'https://image.tmdb.org/t/p/w1280/mxdiaM2tsx8M6W3zLgiPwAkhQfq.jpg', NULL, '2021-09-01', NULL, NULL, NULL, NULL, NULL, 7.01, 2737, 91.528, 7.0, 8, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(28, 1242332, 'Thị Trấn Phủ Tuyết Normal', 'Normal', 'thi-tran-phu-tuyet-normal-2026', NULL, 'Cảnh sát trưởng tạm thời Ulysses, được gọi đến thị trấn phủ tuyết Normal, MN, phát hiện ra một âm mưu tội phạm quốc tế nằm ở trung tâm của vụ chặn còi có vẻ kỳ lạ khi anh ta đến trợ giúp một cặp vợ chồng cướp ngân hàng bị cuốn vào một vụ lộn xộn chết người.', 'https://image.tmdb.org/t/p/w500/rsNdDcCKjCZm9RBMAxL3vMUokKU.jpg', 'https://image.tmdb.org/t/p/w1280/1YU6Hy3x7fUh7dfOzSfjifTp20g.jpg', NULL, '2026-04-16', NULL, NULL, NULL, NULL, NULL, 6.45, 102, 74.864, 8.0, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(29, 980431, 'Huyền Thoại Aang: Tiết Khí Sư Cuối Cùng', 'Avatar Aang: The Last Airbender', 'huyen-thoai-aang-tiet-khi-su-cuoi-cung-2026', NULL, 'Bộ phim tập trung vào giai đoạn hậu chiến tranh, khi thế giới đang trong quá trình tái thiết và đối mặt với những mối đe dọa mới tinh vi hơn từ các tàn dư chính trị. Aang phải gánh vác trọng trách duy trì sự cân bằng giữa bốn quốc gia, đồng thời đối diện với những áp lực của một Thế Thần trưởng thành. Phim hứa hẹn sẽ khai thác sâu hơn về sức mạnh của Aang ở thời kỳ đỉnh cao và mối quan hệ bền chặt của nhóm bạn sau nhiều năm gắn bó.', 'https://image.tmdb.org/t/p/w500/gf7EeEQe22Zu1u55wRT8EAnav93.jpg', 'https://image.tmdb.org/t/p/w1280/sS3zGYFPcfM5pArVNWl6qLyaSmU.jpg', NULL, '2026-10-09', NULL, NULL, NULL, NULL, NULL, 0.00, 0, 80.484, 8.9, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(30, 980477, 'Na Tra 2: Ma Đồng Náo Hải', '哪吒之魔童闹海', 'na-tra-2-ma-dong-nao-hai-2025', NULL, 'Sau kiếp nạn, mặc dù linh hồn của Na Tra và Ngao Bính được bảo toàn, nhưng thân xác của họ sẽ sớm bị hủy hoại hoàn toàn. Thái Ất Chân Nhân dự định sử dụng Bảy Đóa Sen Sắc Màu để tái tạo thân xác cho họ. Tuy nhiên, trong quá trình tái tạo, họ đã gặp phải vô vàn khó khăn. Số phận của Na Tra và Ngao Bính sẽ đi về đâu?', 'https://image.tmdb.org/t/p/w500/qJh6xpfFUg030ldvZruBob3i0Z7.jpg', 'https://image.tmdb.org/t/p/w1280/zxi6WQPVc0uQAG5TtLsKvxYHApC.jpg', NULL, '2025-01-29', NULL, NULL, NULL, NULL, NULL, 8.20, 688, 70.423, 7.7, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(31, 1290821, 'Kẻ Ẩn Dật', 'Shelter', 'ke-an-dat-2026', NULL, 'Michael Mason, một cựu sát thủ chính phủ đang sống ẩn dật trên một hòn đảo hẻo lánh tại Scotland, tình cờ cứu mạng một cô bé tên Jessie sau một cơn bão dữ dội. Hành động nghĩa hiệp này vô tình khiến tung tích của anh bị lộ, buộc Mason phải đối đầu với những bóng ma từ quá khứ và các đặc vụ MI6 đang truy đuổi gắt gao. Để bảo vệ đứa trẻ, anh phải từ bỏ cuộc sống yên bình, vận dụng mọi kỹ năng sinh tồn và chiến đấu để thoát khỏi vòng vây của những kẻ thù nguy hiểm.', 'https://image.tmdb.org/t/p/w500/mucESEbFFqk3ilVpNxEF53IHIVT.jpg', 'https://image.tmdb.org/t/p/w1280/nHxWyy18SvAZ8jJeemtS8k1UNjM.jpg', NULL, '2026-01-28', NULL, NULL, NULL, NULL, NULL, 7.60, 1038, 81.332, 8.2, 9, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(32, 157336, 'Hố Đen Tử Thần', 'Interstellar', 'ho-den-tu-than-2014', NULL, 'Interstellar nói về chuyến hành trình đi tìm một hành tinh mới cho loài người trú ngụ khi mà Trái Đất dần dần không còn là nơi an toàn và sự sống thì đang chết dần với những dịch bệnh trên các loại cây lương thực, đe dọa đến sự tồn tại của loài người một cách mạnh mẽ. Chúng ta sẽ đi theo hành trình của phi hành đoàn gồm Copper, Amelia cùng các thành viên khác trong việc giải cứu các phi hành gia khác đã lên đường khám phá các hành tinh mới để tìm ra hành tinh mới cho loài người trú ngụ', 'https://image.tmdb.org/t/p/w500/if4TI9LbqNIrzkoOgWjX5PZYDYe.jpg', 'https://image.tmdb.org/t/p/w1280/2ssWTSVklAEc98frZUQhgtGHx7s.jpg', NULL, '2014-11-05', NULL, NULL, NULL, NULL, NULL, 8.48, 39809, 77.234, 7.4, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(33, 1368166, 'Cô Hầu Gái', 'The Housemaid', 'co-hau-gai-2025', NULL, 'Từ đạo diễn Paul Feig, một thế giới hỗn loạn sẽ mở ra, nơi sự hoàn hảo chỉ là ảo giác và mọi thứ dường như đều đang che đậy một bí mật đằng sau. Để chạy trốn khỏi quá khứ, Millie (Sydney Sweeney) trở thành bảo mẫu cho gia đình Nina (Amanda Seyfried) và Andrew (Brandon Sklener), một cặp đôi giàu có. Nhưng ngay khi cô chuyển vào sống chung và bắt đầu công việc \"trong mơ\", sự thật dần được hé lộ - đằng sau vẻ ngoài xa hoa lộng lẫy là mối nguy lớn hơn bất cứ thứ gì Millie có thể tưởng tượng. Một trò chơi đầy cám dỗ của bí mật và quyền lực sắp bắt đầu.', 'https://image.tmdb.org/t/p/w500/vpHLCt2bwYmmkGH4soqJNIFLOUQ.jpg', 'https://image.tmdb.org/t/p/w1280/8lgSWWrpS75Hwdm0TZlL1dK7VDD.jpg', NULL, '2025-12-18', NULL, NULL, NULL, NULL, NULL, 7.25, 2183, 71.505, 8.9, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(34, 755898, 'Cuộc Chiến Giữa Các Thế Giới', 'War of the Worlds', 'cuoc-chien-giua-cac-the-gioi-2025', NULL, 'Will Radford — chuyên gia phân tích an ninh mạng hàng đầu của Bộ An ninh Nội địa — chuyên theo dõi các mối đe dọa đến an ninh quốc gia thông qua một chương trình giám sát diện rộng. Nhưng một cuộc tấn công bất ngờ từ một thực thể bí ẩn đã khiến anh bắt đầu nghi ngờ: phải chăng chính phủ đang che giấu điều gì đó… không chỉ với anh mà với toàn thế giới?', 'https://image.tmdb.org/t/p/w500/3e6GQvCA9hguxqfqA75BDvG7Vvp.jpg', 'https://image.tmdb.org/t/p/w1280/iZLqwEwUViJdSkGVjePGhxYzbDb.jpg', NULL, '2025-07-29', NULL, NULL, NULL, NULL, NULL, 4.11, 999, 71.856, 8.0, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(35, 278, 'Nhà Tù Shawshank', 'The Shawshank Redemption', 'nha-tu-shawshank-1994', NULL, 'Nhà tù Shawshank kể về Andrew, một nhân viên nhà băng, bị kết án chung thân sau khi giết vợ và nhân tình của cô. Anh một mực cho rằng mình bị oan. Andy bị đưa tới nhà tù Shawshank. Tại đây, thế giới ngầm của các phạm nhân, sự hà khắc của hệ thống quản giáo xung đột và giành nhau quyền thống trị. Chỉ có các phạm nhân trung lập là bị kẹt ở giữa và có thể bỏ mạng. Làm quen với tay ‘quản lý chợ đen’ Redding, Andy dần thích nghi với cuộc sống tại Shawshank. Song, kế hoạch lớn hơn việc tồn tại ở nhà tù này đang được anh suy tính. Qua con mắt và lời kể của Redding, cuộc vượt ngục vĩ đại này được kể tuần tự cùng một kết thúc bất ngờ', 'https://image.tmdb.org/t/p/w500/zLyG4nquaaZKCA3CJdQCEzTwN1R.jpg', 'https://image.tmdb.org/t/p/w1280/zfbjgQE1uSd9wiPTX4VzsLi0rGG.jpg', NULL, '1994-09-23', NULL, NULL, NULL, NULL, NULL, 8.72, 30402, 71.061, 8.2, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(36, 840464, 'Thảm Họa Thiên Thạch 2: Đại Di Cư', 'Greenland 2: Migration', 'tham-hoa-thien-thach-2-dai-di-cu-2026', NULL, 'Sau ngày tận thế, gia đình Garrity rời boong-ke an toàn ở Greenland, mạo hiểm tất cả để bước vào một hành trình đầy hiểm nguy, băng qua vùng đất hoang tàn của châu Âu nhằm tìm kiếm một mái nhà mới.', 'https://image.tmdb.org/t/p/w500/o3mnfe0nJuD5oBBbGebN3xGYzaK.jpg', 'https://image.tmdb.org/t/p/w1280/wns4x1GyxCudgOZRyhXKjXVJf3T.jpg', NULL, '2026-01-07', NULL, NULL, NULL, NULL, NULL, 6.41, 1106, 69.670, 7.5, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(37, 1242898, 'Quái Thú Vô Hình: Vùng Đất Chết Chóc', 'Predator: Badlands', 'quai-thu-vo-hinh-vung-dat-chet-choc-2025', NULL, 'Trong tương lai, tại một hành tinh hẻo lánh, một Predator non nớt - kẻ bị chính tộc của mình ruồng bỏ - tìm thấy một đồng minh không ngờ tới là Thia và bắt đầu hành trình sinh tử nhằm truy tìm kẻ thù tối thượng. Bộ phim do Dan Trachtenberg - đạo diễn của Prey chỉ đạo và nằm trong chuỗi thương hiệu Quái Thú Vô Hình Predator.', 'https://image.tmdb.org/t/p/w500/6aPy2tMgQLVz2IcifrL1Z2Q9u1t.jpg', 'https://image.tmdb.org/t/p/w1280/gaKFXcB5J1gz0QqYj8bWIfrPc04.jpg', NULL, '2025-11-05', NULL, NULL, NULL, NULL, NULL, 7.74, 2934, 67.266, 6.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(38, 1734, 'Xác Ướp 2: Trở Lại', 'The Mummy Returns', 'xac-uop-2-tro-lai-2001', NULL, 'Đã 8 năm trôi qua kể từ khi Rick và Evelyn lần đầu tiên gặp nhau. Trong phần hai của loạt phim về xác ướp Ai Cập, họ đã kết hôn và có một câu con trai kháu khỉnh 8 tuổi Alex. Lần trở lại này, cả Evelyn và Alex đều gặp nguy hiểm khi cậu bé nghịch ngợm đeo vào tay chiếc vòng của Vua Bọ Cạp còn Evelyn thì phát hiện ra mình là một công chúa Ai Cập trong thế giới cổ xưa...', 'https://image.tmdb.org/t/p/w500/f9mqQwQzGXbmztktVoVO27X7M4a.jpg', 'https://image.tmdb.org/t/p/w1280/7s7WkAFPBsMTprYMbqbgKoppQsR.jpg', NULL, '2001-05-04', NULL, NULL, NULL, NULL, NULL, 6.40, 7668, 60.027, 9.0, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(39, 1579, 'Khải Huyền', 'Apocalypto', 'khai-huyen-2006', NULL, 'Bộ phim hư cấu, lấy đề tài về nền văn minh Châu Mỹ cổ đại, với đế chế Maya đầy huyền bí có thật trong lịch sự nhân loại thống trị Châu Mỹ hơn 1000 năm, với bối cảnh 500 năm sau khi Maya diệt vong, ở nhiều nơi trong rừng già Châu Mỹ, nền văn minh Maya vẫn còn tồn tại với những Kim tự tháp Maya cao vời vợi và sự dựng xây nên văn minh đó đồng nghĩa với sự chinh phục, tiêu diệt biết bao bộ lạc nhỏ xung quanh, cướp bóc những phồn hoa, những của cải, con người, máu và nước mắt để rồi một ngày, cả thế giới ấy bị nhấn chìm vào sự hủy diệt, có phải ấy chính là sự trừng phạt của thần thánh cho những hành động mà họ đã gây cho cho những dân tộc khác ?. Tất cả những sự kiện, những suy nghĩ, những bí ẩn trên về ...', 'https://image.tmdb.org/t/p/w500/cRY25Q32kDNPFDkFkxAs6bgCq3L.jpg', 'https://image.tmdb.org/t/p/w1280/nnmbJvYyDS1VkMOCbxSpdBi3WbJ.jpg', NULL, '2006-12-07', NULL, NULL, NULL, NULL, NULL, 7.62, 6326, 58.399, 7.3, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(40, 1314481, 'Yêu Nữ Thích Hàng Hiệu 2', 'The Devil Wears Prada 2', 'yeu-nu-thich-hang-hieu-2-2026', NULL, 'Hai mươi năm sau màn hóa thân kinh điển vào các vai diễn Miranda, Andy, Emily và Nigel — Meryl Streep, Anne Hathaway, Emily Blunt và Stanley Tucci sẽ chính thức trở lại với những con phố thời thượng của New York và văn phòng sang trọng của Tạp chí Runway trong \"The Devil Wears Prada 2\" (Yêu Nữ Thích Hàng Hiệu 2). Đây là phần phim tiếp theo cực kỳ được mong đợi từ 20th Century Studios, kế thừa sức hút từ hiện tượng điện ảnh năm 2006 từng định hình phong cách cho cả một thế hệ. Bộ phim được đạo diễn bởi David Frankel, kịch bản bởi Aline Brosh McKenna, sản xuất bởi Wendy Finerman, điều hành sản xuất bởi Michael Bederman, Karen Rosenfelt và Aline Brosh McKenna.', 'https://image.tmdb.org/t/p/w500/hhCEHR0OKeVJUiQLtiI6GBbUeAe.jpg', 'https://image.tmdb.org/t/p/w1280/y3fQa7pytlysovXzovpXc1OQlTW.jpg', NULL, '2026-04-29', NULL, NULL, NULL, NULL, NULL, 6.60, 671, 60.195, 8.9, 7, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(41, 1159559, 'Tiếng Thét 7', 'Scream 7', 'tieng-thet-7-2026', NULL, 'Sidney Evans (Neve Campbell), nạn nhân sống sót của một vụ thảm sát nhiều năm trước, giờ đang sống hạnh phúc cùng chồng và con gái ở một thị trấn khác thì tên sát nhân Ghostface mới lại xuất hiện. Những nỗi sợ hãi đen tối nhất của cô trở thành hiện thực khi con gái cô Tatum Evans (Isabel May) trở thành mục tiêu tiếp theo. Quyết tâm bảo vệ gia đình, Sidney buộc phải đối mặt với những kinh hoàng trong quá khứ để chấm dứt cuộc đổ máu một lần và mãi mãi.', 'https://image.tmdb.org/t/p/w500/nXXpliMy4Y0mwRa4OlhOb6GyOEE.jpg', 'https://image.tmdb.org/t/p/w1280/t9J2HXaDuJR7bvIG9XF7mttn4VY.jpg', NULL, '2026-02-25', NULL, NULL, NULL, NULL, NULL, 6.12, 932, 56.735, 8.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(42, 24428, 'Avengers 1:Biệt Đội Siêu Anh Hùng', 'The Avengers', 'avengers-1biet-doi-sieu-anh-hung-2012', NULL, 'The Avengers là bộ phim giả tưởng kể về một nhóm siêu anh hùng với những khả năng đặc biệt, họ bao gồm: Người Sắt, Thor, Đội trưởng Mỹ, và Người Khổng Lồ Xanh Hulk cùng tham gia với tổ chức bảo vệ thế giới SHIELD. Mục đích của SHIELD là nhằm bảo vệ Trái Đất khỏi âm mưu hủy hoại của những thế lực xấu từ ngoài địa cầu mà kẻ cầm đầu là Loki.', 'https://image.tmdb.org/t/p/w500/rX46P5ZwcHOvrkhtYDYhnNf46Bo.jpg', 'https://image.tmdb.org/t/p/w1280/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg', NULL, '2012-04-25', NULL, NULL, NULL, NULL, NULL, 8.03, 38000, 51.501, 8.5, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(43, 1198994, 'Cứu', 'Send Help', 'cuu-2026', NULL, 'Hai đồng nghiệp trở thành những người sống sót duy nhất sau một vụ rơi máy bay và bị mắc kẹt trên một hòn đảo hoang. Tại đây, họ buộc phải gạt bỏ những mâu thuẫn trong quá khứ để hợp tác sinh tồn. Nhưng càng kéo dài, cuộc chiến không chỉ còn là chống chọi với thiên nhiên khắc nghiệt — mà trở thành màn đấu trí và đấu ý chí, nơi chỉ những người đủ tỉnh táo và quyết liệt mới có cơ hội thoát ra sống sót.', 'https://image.tmdb.org/t/p/w500/hu5J1hJYToOxjceeqyXogq5nRwt.jpg', 'https://image.tmdb.org/t/p/w1280/fBh0OlTY5XSHuFrQ7ylXHniwg9s.jpg', NULL, '2026-01-22', NULL, NULL, NULL, NULL, NULL, 7.04, 1574, 52.178, 7.7, 9, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(44, 1038392, 'Ám Ảnh Kinh Hoàng: Nghi Lễ Cuối Cùng', 'The Conjuring: Last Rites', 'am-anh-kinh-hoang-nghi-le-cuoi-cung-2025', NULL, 'Hai nhà điều tra hiện tượng siêu nhiên Ed và Lorraine Warren đối mặt với một vụ án kinh hoàng cuối cùng — nơi họ buộc phải đối đầu với những thực thể bí ẩn đầy đe dọa, thách thức tất cả những gì họ từng tin tưởng.', 'https://image.tmdb.org/t/p/w500/sjvW985erG7NSKJScFNhLbjhyma.jpg', 'https://image.tmdb.org/t/p/w1280/i8MupUe4xgmYXoRNAQMYvuoexSU.jpg', NULL, '2025-09-03', NULL, NULL, NULL, NULL, NULL, 6.90, 1836, 49.475, 8.5, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(45, 1102883, 'Mother Mary: Hào Quang Đơn Độc', 'Mother Mary', 'mother-mary-hao-quang-don-doc-2026', NULL, 'Những vết thương chôn giấu từ lâu trỗi dậy khi ngôi sao nhạc pop biểu tượng Mother Mary tái ngộ người bạn thân đã rạn nứt — đồng thời là nhà thiết kế trang phục cũ của cô, Sam Anselm — ngay trước thềm màn trở lại sân khấu.', 'https://image.tmdb.org/t/p/w500/5k7ndk22c9KPBlRixqou4az0jMQ.jpg', 'https://image.tmdb.org/t/p/w1280/pRrH098VPYiUtDwKOm2mVXVQZdf.jpg', NULL, '2026-04-16', NULL, NULL, NULL, NULL, NULL, 5.86, 64, 46.704, 8.2, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(46, 1265609, 'Cỗ máy chiến tranh', 'War Machine', 'co-may-chien-tranh-2026', NULL, 'Trong nhiệm vụ cuối cùng của khóa huấn luyện Biệt kích Lục quân, một kỹ sư chiến đấu phải dẫn dắt đơn vị chống lại một cỗ máy giết người khổng lồ đến từ thế giới khác.', 'https://image.tmdb.org/t/p/w500/n1IwU8lLbvPZXqjfO7PYKzsmNXe.jpg', 'https://image.tmdb.org/t/p/w1280/6yeVcxFR0j08vlv2OlL6zbewm4D.jpg', NULL, '2026-02-12', NULL, NULL, NULL, NULL, NULL, 7.33, 1774, 51.120, 7.6, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(47, 855435, 'Muôn Mặt Cái Chết', 'Faces of Death', 'muon-mat-cai-chet-2026', NULL, 'Một nữ kiểm duyệt nội dung phát hiện các video giết người cực kỳ chân thật trên mạng. Cô nhận ra có kẻ đang tái hiện các kiểu chết từ phim cũ và phát tán chúng, rồi bị cuốn vào cuộc săn đuổi với chính hắn.', 'https://image.tmdb.org/t/p/w500/vPVY3S57lEooBLJCg6KGdMHkUxm.jpg', 'https://image.tmdb.org/t/p/w1280/hWuHG6e6vM7YbNVW5Z0JcfhmxQq.jpg', NULL, '2026-04-10', NULL, NULL, NULL, NULL, NULL, 5.50, 64, 45.631, 7.2, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(48, 1171145, 'Tội Phạm 101', 'Crime 101', 'toi-pham-101-2026', NULL, 'Lấy bối cảnh thành phố Los Angeles đầy nắng và bụi đường, Tội Phạm 101 kể về một tên trộm nữ trang bí ẩn (Chris Hemsworth) với hàng loạt phi vụ táo bạo khiến cảnh sát phải đau đầu. Trong lúc chuẩn bị cho phi vụ lớn nhất của mình, hắn gặp gỡ một nữ nhân viên bảo hiểm (Halle Berry), người cũng đang vật lộn với những lựa chọn trong đời mình. Trong khi đó, một thanh tra (Mark Ruffalo) đã tìm ra quy luật trong chuỗi các vụ án và đang ráo riết truy đuổi tên trộm, khiến cuộc chơi trở nên căng thẳng hơn bao giờ hết. Khi phi vụ định mệnh đến gần, ranh giới giữa kẻ săn đuổi và con mồi dần trở nên mờ nhạt và cả ba buộc phải đối mặt với những lựa chọn khó khăn và không còn cơ hội để quay đầu lại. Bộ phim được chuyển thể từ tiểu thuyết ngắn nổi tiếng cùng tên của Don Winslow, do Bart Layton (tác giả của American Animals, The Imposter) viết kịch bản và đạo diễn. Dàn diễn viên có sự tham gia của Barry Keoghan, Monica Barbaro, Corey Hawkins, Jennifer Jason Leigh và Nick Nolte.', 'https://image.tmdb.org/t/p/w500/2i7DfVMYX7DyjmQiX64Le8uK45K.jpg', 'https://image.tmdb.org/t/p/w1280/52AkwEfQiJl2HuTPMZ2yC5Bdr9I.jpg', NULL, '2026-02-11', NULL, NULL, NULL, NULL, NULL, 6.97, 997, 50.070, 6.1, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(49, 299536, 'Avengers 3: Cuộc Chiến Vô Cực', 'Avengers: Infinity War', 'avengers-3-cuoc-chien-vo-cuc-2018', NULL, 'Sau chuyến hành trình độc nhất vô nhị không ngừng mở rộng và phát triển vụ trũ điện ảnh Marvel, bộ phim Avengers: Cuộc Chiến Vô Cực sẽ mang đến màn ảnh trận chiến cuối cùng khốc liệt nhất mọi thời đại. Biệt đội Avengers và các đồng minh siêu anh hùng của họ phải chấp nhận hy sinh tất cả để có thể chống lại kẻ thù hùng mạnh Thanos trước tham vọng hủy diệt toàn bộ vũ trụ của hắn.', 'https://image.tmdb.org/t/p/w500/8gHc1cthgTOkmMiOREodCVZgJ7P.jpg', 'https://image.tmdb.org/t/p/w1280/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', NULL, '2018-04-25', NULL, NULL, NULL, NULL, NULL, 8.24, 31979, 49.300, 7.0, 8, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(50, 238, 'Bố Già', 'The Godfather', 'bo-gia-1972', NULL, 'Một câu chuyện kéo dài từ năm 1945 đến năm 1955, một biên niên sử về gia đình tội phạm Corleone người Mỹ gốc Ý. Khi tộc trưởng gia đình tội phạm có tổ chức, Vito Corleone bị ám sát bởi băng nhóm đối thủ, con trai út của ông, Michael đã phải nhúng tay vào tội ác và chống lại đối thủ với việc phát động một chiến dịch trả thù đẫm máu.', 'https://image.tmdb.org/t/p/w500/84MHN3JvOV4ORHgELrQM6SBlhdB.jpg', 'https://image.tmdb.org/t/p/w1280/tSPT36ZKlP2WVHJLM4cQPLSzv3b.jpg', NULL, '1972-03-14', NULL, NULL, NULL, NULL, NULL, 8.69, 22941, 47.963, 7.5, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(51, 1246049, 'Dracula: Bản Tình Ca Bất Diệt', 'Dracula', 'dracula-ban-tinh-ca-bat-diet-2025', NULL, 'Một hoàng tử tuyệt vọng biến thành Dracula và lang thang bất tận qua thời gian, sống chỉ vì lời hứa tìm lại tình yêu của đời mình.', 'https://image.tmdb.org/t/p/w500/hCKkybW6EfSZoOW3xia9ZsQwaUd.jpg', 'https://image.tmdb.org/t/p/w1280/be5SIsRGMckO8tU9lrLcIik70Dy.jpg', NULL, '2025-07-30', NULL, NULL, NULL, NULL, NULL, 7.12, 1205, 46.754, 8.9, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(52, 1010581, 'Tội Lỗi', 'Culpa mía', 'toi-loi-2023', NULL, 'Cô nàng Noah buộc phải bỏ lại thị trấn, bạn trai và bạn bè thân để chuyển đến dinh thự của người cha dượng giàu có. Ở đó, cô gặp người anh kế mới Nick và tính cách của họ xung đột ngay từ đầu. Tuy nhiên, sự hấp dẫn của họ đối với nhau dần dần biến thành một mối tình bị cấm đoán!', 'https://image.tmdb.org/t/p/w500/3Kjcu12lIy0dCQA1756e9zG2slc.jpg', 'https://image.tmdb.org/t/p/w1280/oz4U9eA6ilYf1tyiVuGmkftdLac.jpg', NULL, '2023-06-08', NULL, NULL, NULL, NULL, NULL, 7.74, 4065, 48.117, 8.3, 2, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(53, 1254594, 'Omukade: Con Rết Người', 'โอมุคาเดะ', 'omukade-con-ret-nguoi-2026', NULL, 'Năm 1941, một nhóm lính Nhật và các tù nhân mắc kẹt trong một mỏ quặng bị nguyền rủa ở Thái Lan buộc phải liên thủ để sống sót trước một con quái vật khổng lồ nhiều chân.', 'https://image.tmdb.org/t/p/w500/7RdzEmKj2yy3DttYkvZ6G5cCtoE.jpg', 'https://image.tmdb.org/t/p/w1280/i5c2Tvhn2mZWT43zdwHEliau58j.jpg', NULL, '2026-01-22', NULL, NULL, NULL, NULL, NULL, 5.00, 1, 44.408, 5.0, 2, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(54, 1110034, 'Quái Vật Biển', 'Kraken', 'quai-vat-bien-2026', NULL, 'Bối cảnh đặt vào thời Chiến tranh Lạnh, một tàu ngầm tên lửa Nga biến mất bí ẩn trên Biển Greenland. Đại úy Viktor Voronin (Alexander Petrov) — người em của chỉ huy tàu mất tích — dẫn đầu chiến dịch cứu hộ. Trong khi đó, một căn cứ địa chất ở Bắc Cực vô tình đánh thức con Kraken—một quái vật biển sâu khổng lồ với khả năng ngụy trang siêu việt và trí thông minh đáng sợ. Khi nhóm cứu hộ tiếp cận khu vực tàu ngầm mất tích, họ cũng phải đối mặt với sinh vật huyền thoại đang nổi lên từ đáy đại dương', 'https://image.tmdb.org/t/p/w500/8ExwomWgJoXBdY3u1Otiw2zY9wZ.jpg', 'https://image.tmdb.org/t/p/w1280/oV472EbPedkc5QzqolGc7sCgCnn.jpg', NULL, '2026-02-06', NULL, NULL, NULL, NULL, NULL, 5.80, 48, 47.980, 8.4, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(55, 1368314, 'Khách', 'Passenger', 'khach-2026', NULL, 'Vài tuần sau khi bắt đầu hành trình sống trên xe van, một cặp đôi trẻ chứng kiến một vụ tai nạn kinh hoàng khiến người tài xế thiệt mạng. Không lâu sau, họ bị một thực thể quỷ dị bám theo ráo riết — thứ không thể bị cắt đuôi và luôn lần ra họ dù họ chạy đến bất cứ đâu.', 'https://image.tmdb.org/t/p/w500/39z7di5bi8tW4696SqhN96jxK58.jpg', 'https://image.tmdb.org/t/p/w1280/hl7FEzMqgpsD0RfwMzskzQoiD1M.jpg', NULL, '2026-05-20', NULL, NULL, NULL, NULL, NULL, 5.94, 36, 42.227, 8.7, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(56, 1404791, 'Vong Nhi Cúp Bế', 'ドールハウス', 'vong-nhi-cup-be-2025', NULL, 'Suzuki Yoshie bỗng tìm thấy một con búp bê giống với đứa con gái đã mất của mình, vì quá đau buồn mà vợ chồng cô đã chăm sóc con búp bê trong suốt nhiều năm. Sự việc kinh hoàng xảy ra khi cô phát hiện mình đã có thai, và dường như con búp bê của cô không muốn chia sẻ tình thương với “đứa em” sơ sinh đó.', 'https://image.tmdb.org/t/p/w500/kP3Weds0zmduitEtviLZgK12n1U.jpg', 'https://image.tmdb.org/t/p/w1280/hV6eicjIYxP1v6Qki0bAUMF2Ijf.jpg', NULL, '2025-06-13', NULL, NULL, NULL, NULL, NULL, 7.57, 69, 41.810, 5.4, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(57, 22, 'Cướp Biển Vùng Caribbean: Lời Nguyền Tàu Ngọc Trai Đen', 'Pirates of the Caribbean: The Curse of the Black Pearl', 'cuop-bien-vung-caribbean-loi-nguyen-tau-ngoc-trai-den-2003', NULL, 'Khi chiếc thuyền của gia đình cô bé Elizabeth đi qua vùng biển Caribe nhiều cướp biển họ đã cứu được cậu bé Will Turner. Cả gia đình Elizabeth không hề biết rằng Will là William Turner, con trai của một tên trùm cướp biển khét tiếng.  Nhiều năm sau, mọi chuyện dần dần được hé lộ khi Elizabeth bị ngã xuống biển do một tai nạn và được thuyền trưởng Jack Sparrow cứu thoát.', 'https://image.tmdb.org/t/p/w500/kvDwL2gTf6yxujbsWbsGQB3Z9Wa.jpg', 'https://image.tmdb.org/t/p/w1280/zXMGAtDqJ58P8G3W4bwKyYffPhn.jpg', NULL, '2003-07-09', NULL, NULL, NULL, NULL, NULL, 7.82, 22214, 41.670, 6.8, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(58, 502356, 'Anh Em Super Mario', 'The Super Mario Bros. Movie', 'anh-em-super-mario-2023', NULL, 'The Super Mario Bros. Movie xoay quanh cuộc phiêu lưu ở thế giới Vương quốc Nấm của anh em thợ sửa ống nước Mario và Luigi. Sau khi tình cờ bước tới vùng đất lạ từ một ống nước, Luigi đã bị chia tách với Mario và rơi vào tay quái vật rùa xấu xa Bowser, hắn đang âm mưu độc chiếm thế giới. Trong lúc cố gắng tìm kiếm người anh em của mình, Mario đã chạm mặt anh bạn nấm Toad và công chúa Peach. Từ đây họ sát cánh bên nhau trên hành trình ngăn chặn thế lực hắc ám.', 'https://image.tmdb.org/t/p/w500/gRlfFcpPdjREQ3lgeuAuB10gfbR.jpg', 'https://image.tmdb.org/t/p/w1280/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', NULL, '2023-04-05', NULL, NULL, NULL, NULL, NULL, 7.60, 10739, 42.407, 8.1, 2, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(59, 122, 'Chúa Tể Của Những Chiếc Nhẫn: Sự Trở Lại Của Nhà Vua', 'The Lord of the Rings: The Return of the King', 'chua-te-cua-nhung-chiec-nhan-su-tro-lai-cua-nha-vua-2003', NULL, 'Sauron huy động toàn lực cho trận chiến khốc liệt cuối cùng, tấn công vào Gondor – vùng đất huyết mạch của loài người. Gondor dưới sự lãnh đạo của vị vua nhu nhược trở nên quá mong manh và nguy ngập. Đó chính là lúc những người anh hùng phát huy hết khả năng của mình. Cùng với sự hỗ trợ của các chiến binh Rohan, lực lượng những hồn ma bị nguyền rủa trong khe núi, Aragorn đã thống lĩnh những người Gondor chống lại Sauron, anh đã thực hiện sứ mệnh mà số phận giao phó cho mình, Aragorn sinh ra để trở thành Vua của Gondor, anh đã chứng minh điều đó. Cùng lúc đó, Frodo và Sam tiếp tục dấn sâu vào vùng đất ma quỷ đầy hiểm nguy để thực thi sứ mạng của mình, sứ mạng tiêu hủy Chiếc Nhẫn Quyền Lực. Có thể nói Sự Trở Lại Của Nhà Vua Phim là phần có nội dung hấp dẫn cùng những màn chiến đấu cực hay, cực kỳ hoành tráng.', 'https://image.tmdb.org/t/p/w500/3Y6eymGHCfQkDKU6rev2WiqXMci.jpg', 'https://image.tmdb.org/t/p/w1280/2u7zbn8EudG6kLlBzUYqP8RyFU4.jpg', NULL, '2003-12-17', NULL, NULL, NULL, NULL, NULL, 8.50, 26532, 42.612, 6.1, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(60, 155, 'Kỵ Sĩ Bóng Đêm', 'The Dark Knight', 'ky-si-bong-dem-2008', NULL, 'Người Dơi bước vào giai đoạn cam go nhất trong cuộc chiến chống lại cái ác khi tên tội phạm bậc thầy The Joker xuất hiện. Các tay trùm thuê The Joker giết Người Dơi để trả thù cho chỗ tài sản phi pháp bị anh lật tẩy. Tiếp tay cho The Joker là toàn bộ tội phạm ở thành phố Gotham, những kẻ đang bị bộ ba Người Dơi - Trung úy Gordon - Luật sư Harvey Dent thu hẹp đất sống. Hàng loạt vụ tấn công xảy ra khiến Người Dơi lúng túng. Các quan chức bị sát hại, người dân không dám ra đường buổi tối vì sợ bị giết, mọi lối ra vào thành phố Gotham bị phong tỏa. Tất cả đều do một tay The Joker sắp đặt.', 'https://image.tmdb.org/t/p/w500/7EfSqviKvXwbiGhUjHyUBGVdoiW.jpg', 'https://image.tmdb.org/t/p/w1280/cfT29Im5VDvjE0RpyKOSdCKZal7.jpg', NULL, '2008-07-16', NULL, NULL, NULL, NULL, NULL, 8.53, 35766, 44.275, 7.6, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(61, 337167, 'Năm Mươi Sắc Thái: Tự Do', 'Fifty Shades Freed', 'nam-muoi-sac-thai-tu-do-2018', NULL, 'Anastasia đã trở thành bà Grey, lấy được anh chồng Christian đẹp trai và sống trong ngôi nhà mới nguy nga tráng lệ. Thế nhưng, những bóng ma quá khứ vẫn ám ảnh gia đình hạnh phúc của họ. Người đàn bà đã dẫn Christian Grey vào con đường \"đen tối\" và gã sếp cũ Jack Hyde liên tục tìm cách quấy phá đôi vợ chồng trẻ. Họ phải làm thế nào để giữ được hạnh phúc vừa được tạo dựng.', 'https://image.tmdb.org/t/p/w500/8amqiwYBtvNNp9BWNQN5BiJ299U.jpg', 'https://image.tmdb.org/t/p/w1280/9ywA15OAiwjSTvg3cBs9B7kOCBF.jpg', NULL, '2018-01-17', NULL, NULL, NULL, NULL, NULL, 6.68, 8341, 43.895, 7.5, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(62, 39254, 'Tay Đấm Thép', 'Real Steel', 'tay-dam-thep-2011', NULL, 'Phim đặt trong tương lai không xa, loài người tạo nên những robot siêu đẳng, khi mà quyền Anh robot trở thành môn thể thao phổ biến và có thể thay thế con người trổ tài trên sàn đấm bốc. Nhưng đó cũng là nơi Charlie - một võ sĩ quyền anh nổi tiếng với những cú đấm “thần sầu” - cảm thấy không thể hòa hợp. Đúng lúc ấy, anh tình cờ tìm được 1 chú robot ở bãi phế thải và tin rằng nó sẽ giúp anh vô địch. Trong khi Charlie theo đuổi hy vọng leo lên vị trí dẫn đầu thì một điều bất ngờ khác cũng đến với anh. Đứa con trai lưu lạc bấy lâu đột nhiên xuất hiện và muốn biết nhiều hơn về bố mình…', 'https://image.tmdb.org/t/p/w500/zDSsdnF2Hov7nSLFTTDKinNqAZP.jpg', 'https://image.tmdb.org/t/p/w1280/pjlxrd646cBYznHoPBWTzz6FujX.jpg', NULL, '2011-09-28', NULL, NULL, NULL, NULL, NULL, 7.09, 9126, 48.101, 7.9, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(63, 7451, 'Điệp Viên xXx', 'xXx', 'diep-vien-xxx-2002', NULL, 'Xander xXx Cage vốn nổi tiếng là một người say mê các trò mạo hiểm chết người và cho đến nay vẫn chưa từng bị luật pháp sờ gáy. Nhưng nhân viên tình báo Augustus Gibbons đã buộc xXx cộng tác với chính phủ bằng cách xâm nhập vào một tổ chức tội phạm của Nga. Nhiệm vụ của anh là thu thập thông tin về âm mưu tàn phá trái đất của nhóm phi chính phủ do Yorgi cầm đầu, đổi lại xXx sẽ không phải chôn chân trong nhà đá. Ông tìm cách đưa xXx lọt vào thế giới ngầm của bọn tội phạm mà không bị chúng phát giác. Với lòng dũng cảm và tài năng, anh phải vượt qua một đối thủ “khó nhằn” hơn bất kỳ thử thách nào anh từng đối mặt...', 'https://image.tmdb.org/t/p/w500/xeEw3eLeSFmJgXZzmF2Efww0q3s.jpg', 'https://image.tmdb.org/t/p/w1280/2OHa6ukEq3Hce7Pc2kvu8wkmMFY.jpg', NULL, '2002-08-09', NULL, NULL, NULL, NULL, NULL, 5.99, 4902, 38.870, 6.4, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL);
INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `original_title`, `slug`, `tagline`, `synopsis`, `poster`, `backdrop`, `trailer_url`, `release_date`, `runtime`, `country`, `language`, `budget`, `revenue`, `tmdb_vote_average`, `tmdb_vote_count`, `tmdb_popularity`, `avg_rating`, `rating_count`, `view_count`, `is_approved`, `status`, `is_featured`, `featured_order`, `created_by_user_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(64, 803796, 'Thợ săn quỷ Kpop', 'KPop Demon Hunters', 'tho-san-quy-kpop-2025', NULL, 'Khi các siêu sao Kpop Rumi, Mira và Zoey không bận trình diễn tại các sân vận động cháy vé, họ sử dụng sức mạnh bí mật để bảo vệ người hâm mộ khỏi những mối đe dọa siêu nhiên.', 'https://image.tmdb.org/t/p/w500/y8OyohPhdTtusY0nXd2XdX4NN8W.jpg', 'https://image.tmdb.org/t/p/w1280/w3Bi0wygeFQctn6AqFTwhGNXRwL.jpg', NULL, '2025-06-20', NULL, NULL, NULL, NULL, NULL, 8.02, 2795, 38.543, 9.3, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(65, 1168190, 'Biệt Đội Đập Phá', 'The Wrecking Crew', 'biet-doi-dap-pha-2026', NULL, 'Hai anh em cùng cha khác mẹ Jonny và James đoàn tụ sau cái chết bí ẩn của cha họ. Khi họ tìm kiếm sự thật, những bí mật bị chôn giấu tiết lộ một âm mưu đe dọa chia cắt gia đình họ.', 'https://image.tmdb.org/t/p/w500/yQ8wtSr156Jli2so4rIA0mViT8m.jpg', 'https://image.tmdb.org/t/p/w1280/cz4vLJrmaV1zJlRYbxqtvLzeLWB.jpg', NULL, '2026-01-28', NULL, NULL, NULL, NULL, NULL, 6.96, 1015, 37.839, 8.5, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(66, 603, 'Ma Trận', 'The Matrix', 'ma-tran-1999', NULL, 'The Matrix (MaTrận) là bộ phim khoa học giả tưởng về tương lai. Trong tương lai đó, Thomas, biệt danh Neo, là một hacker luôn có cảm giác khác thường về thế giới thực. Cho tới khi người đàn ông tự xưng là Morpheus tìm đến anh. Người đàn ông này nói cho anh biết, thế giới mà mọi người coi là thực chỉ là một chương trình giả lập để máy móc cai trị con người. Chỉ có một người có thể phá được Ma trận. Những người thật sống sót còn lại cuối cùng và những nhân viên Ma trận đều cùng đi tìm người đó. Và người đó chính là anh – Neo…', 'https://image.tmdb.org/t/p/w500/fE7S6EwaBgRQeqKoDVFoImMmAF4.jpg', 'https://image.tmdb.org/t/p/w1280/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', NULL, '1999-03-31', NULL, NULL, NULL, NULL, NULL, 8.25, 27873, 39.908, 8.3, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(67, 1470130, 'Trợ lý nhà xác', 'The Mortuary Assistant', 'tro-ly-nha-xac-2026', NULL, 'Rebecca Owens, một sinh viên mới tốt nghiệp ngành khoa học nhà xác, nhận công việc ca đêm tại nhà xác River Fields. Ban đầu, công việc có vẻ đơn giản — ướp xác, hoàn thành giấy tờ và giữ gìn vệ sinh. Nhưng khi Rebecca bắt đầu làm ca đêm, mọi chuyện bắt đầu trở nên tăm tối.', 'https://image.tmdb.org/t/p/w500/72AoFPC5TY4DfJwXXS9rPwPeReD.jpg', 'https://image.tmdb.org/t/p/w1280/gM1kQRPwOVW1Eos5tVWqcYmHR5S.jpg', NULL, '2026-02-13', NULL, NULL, NULL, NULL, NULL, 5.52, 106, 39.883, 7.7, 7, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(68, 597, 'Titanic', 'Titanic', 'titanic-1997', NULL, 'Rose DeWitt Bukater, 101 tuổi, hồi nhớ về khoảng thời gian của bà trên tàu Titanic vào 84 năm trước . Khi bà còn là một cô gái trẻ lên tàu Titanic cùng mẹ và chồng sắp cưới. Định mệnh cho cô gặp Jack Dawson, một chàng họa sĩ trẻ tài năng. Rose kể toàn bộ câu chuyện của họ trên chuyến hành trình định mệnh đầu tiên và cuối cùng  của Titanic vào ngày 15 tháng 4 năm 1912.', 'https://image.tmdb.org/t/p/w500/yC2waNaokYeCRHSsYMB8DJK7rGS.jpg', 'https://image.tmdb.org/t/p/w1280/xnHVX37XZEp33hhCbYlQFq7ux1J.jpg', NULL, '1997-12-18', NULL, NULL, NULL, NULL, NULL, 7.90, 27137, 40.481, 6.5, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(69, 120, 'Chúa Tể Của Những Chiếc Nhẫn: Hiệp Hội Nhẫn Thần', 'The Lord of the Rings: The Fellowship of the Ring', 'chua-te-cua-nhung-chiec-nhan-hiep-hoi-nhan-than-2001', NULL, 'Chiếc nhẫn chúa mang sức mạnh bá chủ vô tình được số phận đưa vào tay chàng hobbit trẻ tuổi Frodo. Khi thày phù thủy Gandalf phát hiện ra chiếc nhẫn này đã từng thuộc về bạo chúa Sauron, Frodo phải nhận nhiệm vụ mang nhẫn tới khe núi Hủy diệt để tiêu hủy nó.  Không đơn độc trong hành trình gian khó, Frodo còn tiếp nhận những người đồng hành thuộc các tộc khác nhau: Legolas tộc Elf; Gimli tộc Dwarf; Aragon, Boromir và ba người bạn Hobbit trung thành...', 'https://image.tmdb.org/t/p/w500/2gayIj5yIrvk7BVXUCXHHIomXgR.jpg', 'https://image.tmdb.org/t/p/w1280/a0lfia8tk8ifkrve0Tn8wkISUvs.jpg', NULL, '2001-12-18', NULL, NULL, NULL, NULL, NULL, 8.43, 27533, 38.317, 7.3, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(70, 361743, 'Phi Công Siêu Đẳng: Maverick', 'Top Gun: Maverick', 'phi-cong-sieu-dang-maverick-2022', NULL, 'Sau hơn 30 năm phụng sự với tư cách phi công hàng đầu của hải quân, Pete “Maverick” Mitchell giờ đang làm việc mình yêu thích: bứt phá giới hạn trong vai trò một phi công thử nghiệm dũng cảm. Tuy nhiên, Maverick phải đối đầu với bóng ma quá khứ khi anh trở lại TOPGUN để đào tạo một nhóm học viên ưu tú và đối mặt với Trung úy Bradshaw, con trai của phi công yểm trợ cũ \"Goose\". Sự cạnh tranh gay gắt bùng nổ khi các phi công chuẩn bị cho một nhiệm vụ chuyên biệt đòi hỏi sự hy sinh tột bậc từ những người được chọn bay.', 'https://image.tmdb.org/t/p/w500/yuY9mNG8EgYBwDZKH4RFJHRoAUp.jpg', 'https://image.tmdb.org/t/p/w1280/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', NULL, '2022-05-21', NULL, NULL, NULL, NULL, NULL, 8.16, 10957, 38.082, 7.8, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(71, 1075175, 'Kỳ Nghỉ Thác Loạn', 'How to Have Sex', 'ky-nghi-thac-loan-2023', NULL, 'Ba cô gái người Anh đi nghỉ mát để trải qua nghi lễ tuổi trưởng thành - uống rượu, đi club, trong những ngày hè tuyệt vời nhất của cuộc đời.', 'https://image.tmdb.org/t/p/w500/yQyoFCBLGJH5HXESmJAzaiXw9zU.jpg', 'https://image.tmdb.org/t/p/w1280/akvlTeB0LiNzw9U9YCAB8wwb5Qo.jpg', NULL, '2023-11-02', NULL, NULL, NULL, NULL, NULL, 6.23, 499, 39.509, 7.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(72, 1272837, '28 Năm Sau: Ngôi Đền Tử Thần', '28 Years Later: The Bone Temple', '28-nam-sau-ngoi-den-tu-than-2026', NULL, 'Mở rộng thế giới do Danny Boyle và Alex Garland xây dựng trong loại phim 28 Năm Sau nhưng đồng thời đảo ngược hoàn toàn mọi trật tự vốn có trong thế giới ấy. Nia DaCosta đảm nhận vai trò đạo diễn bộ phim 28 Năm Sau: Thánh Địa Xương. Tiếp nối câu chuyện, bác sĩ Kelson (Ralph Fiennes) bất ngờ rơi vào một mối quan hệ mới đầy bất ngờ, có khả năng làm thay đổi cả thế giới mà ta từng biết. Trong khi đó, cuộc chạm trán của Spike (Alfie Williams) với Jimmy Crystal (Jack O\'Connell) lại biến thành một cơn ác mộng không lối thoát của cậu bé. Trong thế giới của Thánh Địa Xương, những kẻ bị nhiễm bệnh không còn là mối đe dọa sinh tồn lớn nhất mà chính sự vô nhân tính của những kẻ sống sót mới là thứ quái lạ và đáng sợ hơn.', 'https://image.tmdb.org/t/p/w500/dGTV0DVizaRh5fAsrtB95FnGSlf.jpg', 'https://image.tmdb.org/t/p/w1280/hHDNOlATHhre4eZ7aYz5cdyJLik.jpg', NULL, '2026-01-14', NULL, NULL, NULL, NULL, NULL, 7.12, 1222, 37.147, 7.8, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(73, 425274, 'Phi Vụ Thế Kỷ 3: Thoắt Ẩn Thoắt Hiện', 'Now You See Me: Now You Don\'t', 'phi-vu-the-ky-3-thoat-an-thoat-hien-2025', NULL, 'Tứ Kỵ Sĩ chính thức tái xuất, bắt tay cùng các tân binh ảo thuật gia Gen Z trong một phi vụ đánh cắp kim cương liều lĩnh nhất trong sự nghiệp. Họ phải đối đầu với bà trùm Veronika của đế chế rửa tiền nhà Vandenberg (do Rosamund Pike thủ vai) - một người phụ nữ quyền lực và đầy thủ đoạn. Khi kinh nghiệm lão làng của bộ tứ ảo thuật va chạm với công nghệ 4.0 của một mạng lưới tội phạm xuyên lục địa, liệu ai sẽ làm chủ cuộc chơi? Hãy chuẩn bị tinh thần cho những cú xoắn não mà bạn không thể đoán trước!', 'https://image.tmdb.org/t/p/w500/usoYdcapXSsqAM1bDOtD7H42Wxe.jpg', 'https://image.tmdb.org/t/p/w1280/dHSz0tSFuO2CsXJ1CApSauP9Ncl.jpg', NULL, '2025-11-12', NULL, NULL, NULL, NULL, NULL, 6.51, 1511, 37.466, 9.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(74, 27205, 'Kẻ Cắp Giấc Mơ', 'Inception', 'ke-cap-giac-mo-2010', NULL, 'Cobb đánh cắp thông tin từ các mục tiêu của mình bằng cách đi vào giấc mơ của họ. Saito đề nghị xóa sạch tiền án của Cobb như một khoản thanh toán cho việc thực hiện hành vi đầu tiên đối với con trai của đối thủ cạnh tranh ốm yếu của mình.', 'https://image.tmdb.org/t/p/w500/eBtqGWtR5KUiNl6OXHLR3ri6nVm.jpg', 'https://image.tmdb.org/t/p/w1280/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', NULL, '2010-07-15', NULL, NULL, NULL, NULL, NULL, 8.37, 39245, 36.246, 7.8, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(75, 1234821, 'Thế Giới Khủng Long: Tái Sinh', 'Jurassic World Rebirth', 'the-gioi-khung-long-tai-sinh-2025', NULL, 'Thế Giới Khủng Long: Tái Sinh lấy bối cảnh 5 năm sau phần phim Thế Giới Khủng Long: Lãnh Địa, môi trường Trái đất đã chứng tỏ phần lớn là không phù hợp với khủng long. Nhiều loài thằn lằn tiền sử được tái sinh đã chết. Những con chưa chết đã rút lui đến một vùng nhiệt đới hẻo lánh gần phòng thí nghiệm. Địa điểm đó chính là nơi bộ ba Scarlett Johansson, Mahershala Ali và Jonathan Bailey dấn thân vào một nhiệm vụ cực kỳ hiểm nguy.', 'https://image.tmdb.org/t/p/w500/2IVVciw7dPhUlNmYIaz0s1d56SZ.jpg', 'https://image.tmdb.org/t/p/w1280/zNriRTr0kWwyaXPzdg1EIxf0BWk.jpg', NULL, '2025-06-23', NULL, NULL, NULL, NULL, NULL, 6.27, 3350, 34.996, 8.4, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(76, 496243, 'Ký Sinh Trùng', '기생충', 'ky-sinh-trung-2019', NULL, 'Bộ phim xoay quanh hai gia đình hoàn toàn trái ngược: một bên vô cùng giàu có, còn một bên luôn sống trong cảnh nghèo túng. Họ tình cờ gặp gỡ và quen biết nhau sau một biến cố không ngờ.', 'https://image.tmdb.org/t/p/w500/zZydO1LhMhqDAMM86JUi241wT7X.jpg', 'https://image.tmdb.org/t/p/w1280/TU9NIjwzjoKPwQHoHshkFcQUCG.jpg', NULL, '2019-05-30', NULL, NULL, NULL, NULL, NULL, 8.49, 20622, 38.518, 7.1, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(77, 396535, 'Chuyến Tàu Sinh Tử', '부산행', 'chuyen-tau-sinh-tu-2016', NULL, 'Chuyến Tàu Sinh Tử lấy bối cảnh đất nước Hàn bị tấn công bởi một loại virus bí ẩn, biến con người thành những xác sống hung hăng, khát máu. Có mặt trên chuyến tàu từ Seoul tới Busan là một người cha cùng con gái, hai vợ chồng chuẩn bị đón đứa con đầu lòng và một số cô cậu học sinh cấp 3. Khi đại dịch xác sống bất ngờ bùng phát, họ không còn cách nào khác ngoài đương đầu với nó để bảo vệ những người thân yêu của mình. Hành trình 453km từ Seoul tới vùng an toàn Busan bỗng trở thành cuộc chiến khốc liệt để sinh tồn...', 'https://image.tmdb.org/t/p/w500/xMAMpuKpqXI3tfWow59oInjfoPA.jpg', 'https://image.tmdb.org/t/p/w1280/fVpFOcQyHJM2di9upgSIwWD5wac.jpg', NULL, '2016-07-20', NULL, NULL, NULL, NULL, NULL, 7.75, 8358, 34.640, 8.4, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(78, 634649, 'Người Nhện: Không Còn Nhà', 'Spider-Man: No Way Home', 'nguoi-nhen-khong-con-nha-2021', NULL, 'Peter Parker đã bị lộ mặt và không còn có thể tách biệt cuộc sống bình thường của mình với những yêu cầu cao của việc trở thành một Siêu anh hùng. Khi anh ta yêu cầu sự giúp đỡ từ Doctor Strange, mọi thứ càng trở nên nguy hiểm hơn, buộc anh ta phải khám phá ra ý nghĩa thực sự của việc trở thành Người Nhện.', 'https://image.tmdb.org/t/p/w500/y4SQ2dJ1y2LBUnxTH7hCe8sr29c.jpg', 'https://image.tmdb.org/t/p/w1280/zD5v1E4joAzFvmAEytt7fM3ivyT.jpg', NULL, '2021-12-15', NULL, NULL, NULL, NULL, NULL, 7.93, 21972, 37.828, 7.9, 2, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(79, 911430, 'F1 Phim Điện Ảnh', 'F1', 'f1-phim-dien-anh-2025', NULL, 'Phim kể về Sonny Hayes (do Brad Pitt thủ vai), một cựu tay đua F1 lão làng, người đã rời xa đường đua sau một tai nạn kinh hoàng. Anh được thuyết phục quay trở lại thế giới tốc độ để cố vấn cho một tay đua trẻ tuổi, đầy triển vọng nhưng cũng rất liều lĩnh. Cùng nhau, họ phải đối mặt với những thách thức khốc liệt của giải đấu F1, cạnh tranh với những tay đua hàng đầu thế giới và khám phá lại niềm đam mê, đồng thời tìm cách vượt qua những giới hạn của bản thân. Phim hứa hẹn sẽ mang đến những cảnh quay chân thực và những pha đua xe mãn nhãn, được quay ngay trên các đường đua F1 thật sự.', 'https://image.tmdb.org/t/p/w500/14qIfiKSoN9AYvpT9pSU5rieSE7.jpg', 'https://image.tmdb.org/t/p/w1280/rZWkXnIyTLzUJpHSUpOb7vgB0BL.jpg', NULL, '2025-06-25', NULL, NULL, NULL, NULL, NULL, 7.77, 3946, 36.358, 3.6, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(80, 1316092, '“Đồi Gió Hú”', '\"Wuthering Heights\"', 'doi-gio-hu-2026', NULL, 'Một chuyện tình say đắm và đầy giông bão, diễn ra giữa khung cảnh hoang dã của vùng đồng hoang Yorkshire, khắc họa mối quan hệ mãnh liệt nhưng đầy hủy diệt giữa Heathcliff và Catherine Earnshaw.', 'https://image.tmdb.org/t/p/w500/hMcz9mWJU1bPOWsL6ShQaFLwhbv.jpg', 'https://image.tmdb.org/t/p/w1280/vSQSYd2zZTqc0zmHImwWEGGluMI.jpg', NULL, '2026-02-11', NULL, NULL, NULL, NULL, NULL, 6.64, 1013, 38.966, 6.9, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(81, 1641319, 'Xạ Thủ Bắn Tỉa: Vô Tổ Quốc', 'Sniper: No Nation', 'xa-thu-ban-tia-vo-to-quoc-2026', NULL, 'Brandon Beckett và Đặc vụ Zero dẫn đầu một nhiệm vụ giải cứu ở Venezuela khi bạn bè của họ bị bắt làm con tin.', 'https://image.tmdb.org/t/p/w500/tUmARo0TZEK1EaSuS6dU35FhDyU.jpg', 'https://image.tmdb.org/t/p/w1280/7lizs4SuEU2ihkkAa0SZ66NtHbl.jpg', NULL, '2026-04-07', NULL, NULL, NULL, NULL, NULL, 6.50, 47, 35.365, 8.6, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(82, 299534, 'Avengers 4: Hồi Kết', 'Avengers: Endgame', 'avengers-4-hoi-ket-2019', NULL, 'Sau sự kiện hủy diệt tàn khốc, vũ trụ chìm trong cảnh hoang tàn. Với sự trợ giúp của những đồng minh còn sống sót, biệt đội siêu anh hùng Avengers tập hợp một lần nữa để đảo ngược hành động của Thanos và khôi phục lại trật tự của vũ trụ.', 'https://image.tmdb.org/t/p/w500/8go3YE9sBMQaCXEx23j6BAfeuxd.jpg', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', NULL, '2019-04-24', NULL, NULL, NULL, NULL, NULL, 8.24, 27734, 36.709, 6.5, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(83, 1684226, 'Cô Dâu Của Năm', 'Bruid van die Jaar', 'co-dau-cua-nam-2026', NULL, 'Khi giấc mơ xây dựng gia đình riêng của Lienkie tan vỡ, cô vạch ra một kế hoạch đầy toan tính để giành danh hiệu \"Cô dâu của Năm\" và trả đũa người yêu cũ.', 'https://image.tmdb.org/t/p/w500/geFc71rCYM8fErbROLY6n1LfAS6.jpg', 'https://image.tmdb.org/t/p/w1280/es6wAAA72qIKGecMggiRZNQK0fa.jpg', NULL, '2026-05-15', NULL, NULL, NULL, NULL, NULL, 7.30, 18, 31.478, 8.5, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(84, 269955, 'Ám Ảnh Dục Vọng', '인간중독', 'am-anh-duc-vong-2014', NULL, 'Bối cảnh của phim được lấy vào năm 1969, nội dung xoay quanh đại tá Kim Jin-Pyeong, người mới trở về Hàn Quốc sau khi đi đánh thuê cho quân đội Mỹ trong Chiến tranh Việt Nam. Anh được chỉ huy quân đội cũng là cha vợ của mình và hầu hết mọi người trong căn cứ quân sự kính trọng. Tuy nhiên, Kim Jin-Pyeong cũng gặp phải những tổn thương bên trong do hậu quả của chiến tranh.  Một ngày nọ, Kyung Woo-Jin được chuyển sang làm việc cho Kim Jin-Pyeong. Kyung Woo-Jin là kiểu người sẽ nói hoặc làm bất cứ điều gì để làm hài lòng cấp trên của mình. Chẳng bao lâu, đại tá Kim Jin-Pyeong gặp Jong Ga-Heun, vợ của cấp dưới mới của anh. Hai vợ chồng cấp dưới cũng mới chuyển đến ngôi nhà bên kia đường của nhà đại tá Kim Jin-Pyeong và vợ. Vào một buổi tối định mệnh, đại tá Kim Jin-Pyeong chơi đùa với một con chim nhốt trên hiên nhà của hàng xóm, đó cũng là khoảnh khắc mà anh và Jong Ga-Heun trao trái tim cho nhau ngay từ cái nhìn đầu tiên, để rồi phát triển một mối quan hệ vụng trộm không đúng đắn…', 'https://image.tmdb.org/t/p/w500/zMCeJiRbV7Z5TFA8JpALExAQra.jpg', 'https://image.tmdb.org/t/p/w1280/iGBbWXmAIgpiWg9Mx2D2gLzbg4n.jpg', NULL, '2014-05-14', NULL, NULL, NULL, NULL, NULL, 6.70, 81, 36.113, 7.5, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(85, 11, 'Chiến Tranh Giữa Các Vì Sao: Phần IV - Niềm Hy Vọng Mới', 'Star Wars', 'chien-tranh-giua-cac-vi-sao-phan-iv-niem-hy-vong-moi-1977', NULL, 'Luke Skywalker sống trên một trang trại ở hành tinh Tatooine bụi bặm cùng với cô và chú của anh. Luke là một thanh niên gan dạ và rất nóng lòng được trở thành một chiến binh nổi lọan. Lúc này, tên Darth Vader tàn bạo đã thôn tính cả thiên hà và đang hoàn thành một vũ khí hủy diệt khủng khiếp, Death Star. Công chúa Leia, người dẫn đầu phong trào nổi lọan, biết được kế họach này và tìm cách báo cho Obi-Wan Kenobi, một nhà tu hành già nua sống ẩn dật có sức mạnh phi thường. Vô tình tìm thấy mẩu tin báo nguy của công chúa dấu trong người máy R2D2, Luke lên đường tìm kiếm Obi-Wan Kenobi để hợp sức cùng nhau cứu công chúa cũng như giải thóat cả thiên hà...', 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', 'https://image.tmdb.org/t/p/w1280/yUiXA68FfQeA8cRBhd0Ao0jIRZt.jpg', NULL, '1977-05-25', NULL, NULL, NULL, NULL, NULL, 8.21, 22311, 36.754, 7.4, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(86, 1662317, 'Vụ đụng xe thảm khốc', 'The Crash', 'vu-dung-xe-tham-khoc-2026', NULL, 'Thiếu nữ nọ lao xe vào một tòa nhà, khiến bạn trai và bạn của anh thiệt mạng. Tưởng chỉ là tai nạn thương tâm, nhưng hóa ra lại là một vụ án mạng trong bộ phim tài liệu này.', 'https://image.tmdb.org/t/p/w500/veskdPx4YUTmkrFrTs6zRJ8VV4E.jpg', 'https://image.tmdb.org/t/p/w1280/2iqLoDsatVBwAvHTEzI71p3qBe9.jpg', NULL, '2026-05-14', NULL, NULL, NULL, NULL, NULL, 6.58, 56, 35.065, 7.2, 2, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(87, 424, 'Bản Danh Sách Của Schindler', 'Schindler\'s List', 'ban-danh-sach-cua-schindler-1993', NULL, 'Bản danh sách của Schindler (Schindler`s List) là một bộ phim truyện sản xuất năm 1993 của Hoa Kỳ về Oskar Schindler, một nhà kinh doanh người Đức. Phim bắt đầu vào năm 1939 với sự tập trung người Ba Lan gốc Do Thái của chính quyền Đức Quốc Xã sau khi xâm lược Ba Lan, từ việc bao vây, giam lỏng trong vùng tới xây dựng những khu tập trung Kraków Ghetto không lâu sau khi Đệ nhị thế chiến bắt đầu. Trong lúc đó, Oskar Schindler (Liam Neeson), một doanh nhân thất bại, đến thành phố từ Sudetenland với những hy vọng làm giàu.', 'https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', 'https://image.tmdb.org/t/p/w1280/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', NULL, '1993-12-15', NULL, NULL, NULL, NULL, NULL, 8.57, 17454, 33.902, 6.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(88, 533535, 'Deadpool và Wolverine', 'Deadpool & Wolverine', 'deadpool-va-wolverine-2024', NULL, 'Wade Wilson, chán nản, đang cố gắng sống cuộc đời bình thường sau những ngày làm lính đánh thuê không mấy lương thiện, Deadpool. Nhưng khi quê hương của anh đứng trước nguy cơ diệt vong, Wade buộc phải khoác lại bộ đồ một lần nữa, cùng với một Wolverine còn miễn cưỡng hơn.', 'https://image.tmdb.org/t/p/w500/lfY2CfmxyN9OvxmFuap6aejViJn.jpg', 'https://image.tmdb.org/t/p/w1280/ufpeVEM64uZHPpzzeiDNIAdaeOD.jpg', NULL, '2024-07-24', NULL, NULL, NULL, NULL, NULL, 7.57, 8653, 34.795, 7.1, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(89, 19995, 'Avatar', 'Avatar', 'avatar-2009', NULL, 'Avatar là câu chuyện về người anh hùng “bất đắc dĩ” Jake Sully – một cựu sĩ quan thủy quân lục chiến bị liệt nửa thân. Người anh em sinh đôi của anh được chọn để tham gia vào chương trình cấy gien với người ngoài hành tinh Na’vi nhằm tạo ra một giống loài mới có thể hít thở không khí tại hành tinh Pandora. Giống người mới này được gọi là Avatar. Sau khi anh của Jake bị giết, Jake được chọn để thay thế anh mình và đã trở thành một Avatar, Jake có nhiệm vụ đi tìm hiểu và nghiên cứu hành tinh Pandora. Những thông tin mà anh thu thập được rất có giá trị cho chiến dịch xâm chiếm hành tinh xanh thứ hai này của loài người.', 'https://image.tmdb.org/t/p/w500/bxp5IUY05jLGeZ5bW85W2NF6Rgi.jpg', 'https://image.tmdb.org/t/p/w1280/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg', NULL, '2009-12-16', NULL, NULL, NULL, NULL, NULL, 7.60, 33961, 34.689, 7.0, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(90, 671, 'Harry Potter và Hòn Đá Phù Thủy', 'Harry Potter and the Philosopher\'s Stone', 'harry-potter-va-hon-da-phu-thuy-2001', NULL, 'Harry Potter và Hòn Đá Phù Thủy là bộ phim đầu tiên trong series phim “Harry Potter” được xây dựng dựa trên tiểu thuyết của nhà văn J.K.Rowling. Nhân vật chính của phim, Harry Potter - một cậu bé 11 tuổi sau khi mồ côi cha mẹ đã bị gửi đến nhà dì dượng của mình, gia đình Dursley. Tuy nhiên, cậu bé bị ngược đãi và không hề biết về thân phận thực sự của mình.  Vào sinh nhật thứ 11 của Harry, một người lai khổng lồ là Rubeus Hagrid đã đến tìm cậu bé để đưa cậu về trường Pháp Thuật Hogwarts. Lúc này, Harry mới biết được mình là phù thủy và một phần câu chuyện về cha mẹ mình, những người đã bị Voldemort giết hại. Cùng với trí thông minh và lòng dũng cảm, cậu bé đã cùng những người bạn của mình khám phá những điều bí mật nguy hiểm về thế giới của phép thuật...', 'https://image.tmdb.org/t/p/w500/9Mi8yPrkA0EefbVyE0CHs8tajsg.jpg', 'https://image.tmdb.org/t/p/w1280/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg', NULL, '2001-11-16', NULL, NULL, NULL, NULL, NULL, 7.90, 29550, 35.098, 8.9, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(91, 680, 'Chuyện Tào Lao', 'Pulp Fiction', 'chuyen-tao-lao-1994', NULL, 'Những câu chuyện tưởng chừng tầm phào về 2 gã găng tơ trên đường thực hiện mệnh lệnh của ông chủ với 1 võ sĩ quyền anh giết chết người phải chạy trốn có vẻ không liên quan nhưng khi ghép lại người xem sẽ có 1 bức tranh tổng thể, đặc trưng cho phong cách của đạo diễn Quentin Tarantino: đậm chất bạo lực, máu me.', 'https://image.tmdb.org/t/p/w500/ihynkOAH6FLNgG1kqM5ep9GSHZS.jpg', 'https://image.tmdb.org/t/p/w1280/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', NULL, '1994-09-10', NULL, NULL, NULL, NULL, NULL, 8.50, 30190, 35.513, 8.1, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(92, 1234731, 'Đụng Độ Siêu Trăn', 'Anaconda', 'dung-do-sieu-tran-2025', NULL, 'Một nhóm bạn thân đang khủng hoảng tuổi trung niên quyết định lên đường vào rừng rậm để làm lại bộ phim yêu thích thời trẻ. Nhưng hành trình hoài niệm nhanh chóng biến thành cuộc chiến sinh tồn dữ dội, khi họ phải đối mặt với thiên tai, rắn khổng lồ, và cả những tên tội phạm nguy hiểm.', 'https://image.tmdb.org/t/p/w500/4N2cVrDQ0T8LIvA5rjPefBTxqcL.jpg', 'https://image.tmdb.org/t/p/w1280/swxhEJsAWms6X1fDZ4HdbvYBSf9.jpg', NULL, '2025-12-24', NULL, NULL, NULL, NULL, NULL, 5.88, 1161, 32.857, 7.6, 5, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(93, 1383731, 'Người bảo vệ', 'Protector', 'nguoi-bao-ve-2026', NULL, 'Cuộc sống yên bình của Nikki, một cựu anh hùng chiến tranh, bị đảo lộn khi con gái cô bị bắt cóc. Bị cuốn vào thế giới ngầm tội phạm trong khi bị cảnh sát và quân đội truy đuổi, cô phải chiến đấu để giải cứu con gái mình.', 'https://image.tmdb.org/t/p/w500/icOZpnGuH9YrEaW3wrw5GJaXGih.jpg', 'https://image.tmdb.org/t/p/w1280/vpuPY4UziUCxv7gYYoaZQ3LX7to.jpg', NULL, '2026-02-20', NULL, NULL, NULL, NULL, NULL, 6.40, 58, 32.720, 6.8, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(94, 1233413, 'Tội Đồ', 'Sinners', 'toi-do-2025', NULL, 'Cố gắng bỏ lại cuộc sống đầy rắc rối của mình, hai anh em sinh đôi trở về quê hương để bắt đầu lại, chỉ để phát hiện ra rằng một cái ác thậm chí còn lớn hơn đang chờ đợi để chào đón họ trở lại.', 'https://image.tmdb.org/t/p/w500/aXFWi3ir9vHqAz0m3XIuD92vPsQ.jpg', 'https://image.tmdb.org/t/p/w1280/nAxGnGHOsfzufThz20zgmRwKur3.jpg', NULL, '2025-04-16', NULL, NULL, NULL, NULL, NULL, 7.49, 4526, 32.611, 7.6, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(95, 1306368, 'Ranh giới tội ác', 'The Rip', 'ranh-gioi-toi-ac-2026', NULL, 'Lòng tin rạn nứt khi đội cảnh sát Miami phát hiện thấy hàng triệu đô la tiền mặt bên trong một nhà chứa đồ đổ nát, khiến mọi người – và mọi thứ – bị đặt vào vòng nghi vấn.', 'https://image.tmdb.org/t/p/w500/6xL4Ei29kVIR8BXYyTAVMsggs87.jpg', 'https://image.tmdb.org/t/p/w1280/3F2EXWF1thX0BdrVaKvnm6mAhqh.jpg', NULL, '2026-01-13', NULL, NULL, NULL, NULL, NULL, 7.07, 1619, 32.552, 7.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(96, 454639, 'He-Man và Những Chiến Binh Vũ Trụ', 'Masters of the Universe', 'he-man-va-nhung-chien-binh-vu-tru-2026', NULL, 'Thương hiệu huyền thoại trở lại màn ảnh rộng. Sau 15 năm thất lạc, Thanh Gươm Quyền Năng đưa Hoàng tử Adam (Nicholas Galitzine) trở về hành tinh Eternia và phát hiện quê hương đã rơi vào sự cai trị tàn bạo của Skeletor (Jared Leto). Để cứu gia đình và thế giới của mình, Adam phải sát cánh cùng những đồng minh thân cận như Teela (Camila Mendes) và Duncan/Man-At-Arms (Idris Elba), đồng thời chấp nhận định mệnh thật sự của mình: trở thành He-Man - người đàn ông mạnh nhất vũ trụ.', 'https://image.tmdb.org/t/p/w500/3zJKDkvyTz3g6VpCS6RtaufYV0j.jpg', 'https://image.tmdb.org/t/p/w1280/piV2OnzTZCyGBP9JCjlHIgKGlfo.jpg', NULL, '2026-06-03', NULL, NULL, NULL, NULL, NULL, 0.00, 0, 33.831, 6.9, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(97, 1325734, 'Cú Sốc', 'The Drama', 'cu-soc-2026', NULL, 'Một cặp đôi đang hạnh phúc chuẩn bị kết hôn bất ngờ bị thử thách khi một biến cố ngoài dự kiến khiến cả tuần lễ cưới của họ rơi vào hỗn loạn.', 'https://image.tmdb.org/t/p/w500/2r4p7IXUnbw8JkrsJK2vbhVIE2J.jpg', 'https://image.tmdb.org/t/p/w1280/rw1WmxUvmbwRsbAX12m6toIg04j.jpg', NULL, '2026-03-26', NULL, NULL, NULL, NULL, NULL, 6.92, 812, 33.641, 9.0, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(98, 1022789, 'Những Mảnh Ghép Cảm Xúc 2', 'Inside Out 2', 'nhung-manh-ghep-cam-xuc-2-2024', NULL, 'Những Mảnh Ghép Cảm Xúc 2 sẽ quay trở lại phần tâm trí mới của cô bé thiếu niên Riley. Một ngày, trụ sở chính đột ngột bị phá hủy để nhường chỗ cho một thứ hoàn toàn mới: Một cảm xúc mới! Vui Vẻ, Buồn Bã, Giận Dữ, Sợ Hãi và Chán Ghét phải \'chào đón\' sự xuất hiện của một loại cảm xúc mới là Lo Âu. Và có vẻ như cô ấy không chỉ xuất hiện một mình.', 'https://image.tmdb.org/t/p/w500/wAIFnJ5OeFU7tTnCWHiROsszS29.jpg', 'https://image.tmdb.org/t/p/w1280/p5ozvmdgsmbWe0H8Xk7Rc8SCwAB.jpg', NULL, '2024-06-11', NULL, NULL, NULL, NULL, NULL, 7.55, 6679, 31.411, 5.4, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(99, 129, 'Vùng Đất Linh Hồn', '千と千尋の神隠し', 'vung-dat-linh-hon-2001', NULL, 'Câu chuyện kể về cô bé bướng bỉnh Chihiro. Gia đình của Chihiro chuyển từ thành phố về quê sinh sống, và Chihiro chẳng thích thú tí nào với sự thay đổi này.  Bố của Chihiro là một tay lái xe tệ hại và có một trí nhớ \"quá tồi\", ông đã lái xe lạc đường đến một thành phố bị bỏ hoang, không bóng người. Bị cuốn hút bởi mùi vị thơm ngon của thức ăn, bố mẹ của Chihiro bắt đầu \"thưởng thức\", nhưng kết quả họ bị biến thành những con heo mập. Còn thành phố không người kia, sau khi trời tối, tất cả sống dậy, những bóng ma bắt đầu xuất hiện và hoạt động. Cô bé bướng bỉnh phải làm gì để cứu bố mẹ mình và thoát khỏi đây?', 'https://image.tmdb.org/t/p/w500/pNHppsjxGBcRUCFlXQh0briymTN.jpg', 'https://image.tmdb.org/t/p/w1280/dyJvKsNs2KP8qQnAXbRwDjblViy.jpg', NULL, '2001-07-20', NULL, NULL, NULL, NULL, NULL, 8.53, 18310, 35.544, 9.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(100, 1084187, 'Khá nguy hiểm', 'Pretty Lethal', 'kha-nguy-hiem-2026', NULL, 'Một đoàn vũ công ba lê phải chiến đấu để sinh tồn khi cố gắng trốn thoát khỏi một quán trọ hẻo lánh sau khi xe buýt của họ bị hỏng trên đường đến một cuộc thi khiêu vũ.', 'https://image.tmdb.org/t/p/w500/znTPnXCK3lEQJgqXCvP7e5FUz6f.jpg', 'https://image.tmdb.org/t/p/w1280/z3bzhmC0CPikWeerUkLO73YvGrC.jpg', NULL, '2026-03-13', NULL, NULL, NULL, NULL, NULL, 6.79, 379, 31.946, 7.0, 7, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(101, 1122573, 'Trong Vùng Xám', 'In the Grey', 'trong-vung-xam-2026', NULL, 'Khi một tên bạo chúa tàn nhẫn cướp đi khối tài sản trị giá 1 tỷ đô la, một đội đặc nhiệm tinh nhuệ hoạt động bí mật trong bóng tối toàn cầu được giao nhiệm vụ đoạt lại số tiền đó trong một phi vụ mà với bất kỳ ai khác cũng gần như là nhiệm vụ tự sát. Thành thạo thao túng quyền lực và tầm ảnh hưởng không kém gì sử dụng vũ khí tự động và thuốc nổ hạng nặng, họ bước vào một vụ cướp tưởng chừng bất khả thi rồi nhanh chóng bị cuốn vào một cuộc chiến toàn diện của chiến lược, lừa dối và sinh tồn.', 'https://image.tmdb.org/t/p/w500/dQgIcW6Th08kMRf2HBoYWoFE6OD.jpg', 'https://image.tmdb.org/t/p/w1280/oBft4BZeoDQzTT9ZGijClr76qvK.jpg', NULL, '2026-05-13', NULL, NULL, NULL, NULL, NULL, 6.30, 60, 32.350, 8.2, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(102, 27, 'Giai Điệu Dục Cảm', '9 Songs', 'giai-dieu-duc-cam-2004', NULL, 'Matt, một nhà nghiên cứu về sông băng trẻ tuổi, bay vút qua vùng băng giá rộng lớn, im lặng của Nam Cực khi anh nhớ lại mối tình của mình với Lisa. Họ gặp nhau tại một buổi hòa nhạc rock đông đúc trong hội trường âm nhạc rộng lớn - Học viện Brixton ở London. Họ đang ở trên giường vào cuối đêm. Cùng nhau, trong khoảng thời gian vài tháng, họ theo đuổi niềm đam mê tình dục chung mà các giai đoạn không thể tránh khỏi diễn ra trái ngược với chín bài hát trong buổi hòa nhạc trực tiếp.', 'https://image.tmdb.org/t/p/w500/91O7z0vo7MiNWd5xD2BoivwbQsb.jpg', 'https://image.tmdb.org/t/p/w1280/qU7tNIMpRqkizIObXfkJY3haTqh.jpg', NULL, '2004-07-16', NULL, NULL, NULL, NULL, NULL, 5.54, 579, 31.307, 8.0, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(103, 808, 'Shrek', 'Shrek', 'shrek-2001', NULL, 'Vương quốc Xa thật xa là nơi các nhân vật cổ tích sinh sống. Shrek, gã chằn xanh đang sống yên bình tại đầm lầy của mình. Bỗng nhiên, khu đầm trở thành nơi \"tị nạn\" của các nhân vật cổ tích đang bị lãnh chúa Farquaad săn đuổi. Để khỏi phải \"chung đụng\" với đám dân ở nhờ ồn ào, Shrek ký giao kèo cùng Farquaad. Gã sẽ đi cứu công chúa Fiona, đang bị giam giữ trong tòa tháp cao vợi, và được rồng canh giữ. Farquaad có được cô dâu trong mộng thì Farquaad phải để các nhân vật cổ tích kia được yên.', 'https://image.tmdb.org/t/p/w500/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', 'https://image.tmdb.org/t/p/w1280/40Wtp7kMG6mZ4d5T1jfrd8qrvD4.jpg', NULL, '2001-05-18', NULL, NULL, NULL, NULL, NULL, 7.76, 18740, 30.906, 9.2, 3, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(104, 315635, 'Người Nhện: Trở Về Nhà', 'Spider-Man: Homecoming', 'nguoi-nhen-tro-ve-nha-2017', NULL, 'Tạm biệt hai franchise về thời sinh viên, Spider-Man: Homecoming sẽ lần đầu tiên đưa các khán giả đến với cuộc sống trung học của Peter Paker – siêu anh hùng Người Nhện. Liệu một cậu bé chưa trưởng thành sẽ làm thế nào để cân bằng cuộc sống bình thường và trách nhiệm của một anh hùng giải cứu thế giới. Đây cũng là lần đầu tiên, series Người Nhện có sự tham gia sản xuất của Marvel Studio và sự xuất hiện của Iron Man – Robert Downey Jr.', 'https://image.tmdb.org/t/p/w500/tNm6pNf9Xe1gPKu4xqPEWj0issu.jpg', 'https://image.tmdb.org/t/p/w1280/tPpYGm2mVecue7Bk3gNVoSPA5qn.jpg', NULL, '2017-07-05', NULL, NULL, NULL, NULL, NULL, 7.33, 23150, 32.807, 5.5, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(105, 216015, 'Năm Mươi Sắc Thái', 'Fifty Shades of Grey', 'nam-muoi-sac-thai-2015', NULL, 'Câu chuyện bắt đầu khi cô sinh viên Anastasia Steele (Dakota Johnson thủ vai) tới phỏng vấn triệu phú trẻ tuổi Christian Grey (Jamie Dornan) cho tờ tạp chí của trường. Ana đơn giản, trong sáng đã lọt vào mắt xanh của kẻ luôn thích kiểm soát mọi việc là Christian. Anh bắt đầu tiếp cận Ana và cuốn cô vào vòng xoáy của tình ái và nhục cảm. Nhưng đây không phải câu chuyện tình đơn thuần giữa chàng hoàng tử giàu sang lịch lãm và cô gái ngây thơ chân chất.', 'https://image.tmdb.org/t/p/w500/rtMfrW81vdFw245Md7NqoQ90MtA.jpg', 'https://image.tmdb.org/t/p/w1280/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', NULL, '2015-02-11', NULL, NULL, NULL, NULL, NULL, 5.87, 12372, 31.315, 7.4, 9, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(106, 557, 'Người Nhện', 'Spider-Man', 'nguoi-nhen-2002', NULL, 'Peter Parker là một sinh viên trẻ và nhút nhát, đã sống với dì May và chú Ben kể từ khi cha mẹ anh ta mất khi anh ta còn rất nhỏ. Peter yêu người hàng xóm xinh đẹp của mình, nhưng sự thiếu lôi cuốn của anh ta không khiến anh ta trở nên nổi tiếng ở trường trung học. Một ngày nọ, anh ta bị cắn bởi một con nhện đã bị biến đổi gen, phát hiện ra ngày hôm sau anh ta sở hữu sức mạnh khác thường: anh ta có sức mạnh và sự nhanh nhẹn của một con nhện. Cuộc phiêu lưu của Người Nhện, dựa trên truyện tranh nổi tiếng Stan Lee và Steve Ditko, đã càn quét phòng vé Mỹ và phá vỡ kỷ lục phá vỡ kỷ lục vào cuối tuần đầu tiên của anh: 114 triệu đô la, lần đầu tiên trong lịch sử, anh tìm cách phá vỡ Rào cản 100 triệu đô la vào một ngày cuối tuần bình thường.', 'https://image.tmdb.org/t/p/w500/w55KSeyhH3nXjzx7AhbNq0DO3zt.jpg', 'https://image.tmdb.org/t/p/w1280/zQ8AxTPiCiS5nnwXpwTBPBHSaa5.jpg', NULL, '2002-05-01', NULL, NULL, NULL, NULL, NULL, 7.33, 20644, 30.255, 8.8, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(107, 950396, 'Hẻm Núi - The Gorge', 'The Gorge', 'hem-nui-the-gorge-2025', NULL, 'Hai đặc vụ được huấn luyện bài bản dần trở nên thân thiết từ xa sau khi được cử đến canh gác hai bên hẻm núi bí ẩn. Khi thế lực tà ác ở bên dưới xuất hiện, họ phải hợp tác để sống sót trước những gì ẩn chứa bên trong.', 'https://image.tmdb.org/t/p/w500/kQwCN38RRlJFer6GDB3hR3Ay1mk.jpg', 'https://image.tmdb.org/t/p/w1280/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg', NULL, '2025-02-13', NULL, NULL, NULL, NULL, NULL, 7.63, 3713, 30.812, 7.9, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(108, 218, 'Kẻ Hủy Diệt', 'The Terminator', 'ke-huy-diet-1984', NULL, 'Năm 2029, những kẻ cai trị Trái Đất quyết định gửi về quá khứ một robot sát thủ mang tên The Terminator - Kẻ Hủy Diệt để thay đổi quá khứ. Nhiệm vụ của tên robot này là giết chết Sarah Connor, người có vai trò quyết định trong cuộc kháng chiến của nhân loại sau này.', 'https://image.tmdb.org/t/p/w500/dFci3DJsm1hNZbhFJNJ5XvssE5v.jpg', 'https://image.tmdb.org/t/p/w1280/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg', NULL, '1984-10-26', NULL, NULL, NULL, NULL, NULL, 7.68, 14589, 30.510, 7.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(109, 14836, 'Cô Bé Coraline', 'Coraline', 'co-be-coraline-2009', NULL, 'Khi Coraline chuyển đến một ngôi nhà cũ, cô cảm thấy buồn chán và bị cha mẹ bỏ rơi. Cô tìm thấy một cánh cửa ẩn với một lối đi bằng gạch. Trong đêm, cô băng qua hành lang và tìm thấy một thế giới song song, nơi mọi người đều có nút thay vì mắt, với cha mẹ chăm sóc và tất cả ước mơ của cô đều trở thành sự thật. Khi Người Mẹ khác mời Coraline ở lại thế giới của mình mãi mãi, cô gái từ chối và thấy rằng thực tế thay thế nơi cô bị mắc kẹt chỉ là một thủ thuật để thu hút cô.', 'https://image.tmdb.org/t/p/w500/p8YSnUyQGZQkW1NSgVvn7ubWWCn.jpg', 'https://image.tmdb.org/t/p/w1280/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', NULL, '2009-02-05', NULL, NULL, NULL, NULL, NULL, 7.91, 8958, 29.766, 7.1, 8, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(110, 979, 'Chuyện Đã Rồi', 'Irréversible', 'chuyen-da-roi-2002', NULL, 'Irreversible có một trong những cảnh sex kinh hoàng nhất trong lịch sử điện ảnh hiện đại.\\r Đó là cảnh Alex (Monica Bellucci) tức giận bỏ một bữa tiệc ra về khi bị bạn trai đem ra làm trò cười. Trên đường về nhà, cô vô tình chứng kiến kẻ ma cô có tên le Tenia đánh đập một gái điếm chuyển giới. Alex bị le Tenia để ý. Hắn theo cô xuống đường hầm, đẩy cô vào tường và cưỡng hiếp.\r Một trong những điều khiến cảnh quay này làm người xem sởn da gà và cảm giác như thật là bởi nó là cảnh quay liền. Trên thực tế, cảnh quay này cũng được quay nhiều đúp và hiệu ứng quay liên tục chỉ được tạo ra bằng kỹ xảo.\r Đạo diễn Gaspar Noe cho biết: \\\"Khóa quần vẫn được giữ nguyên trong lúc chúng tôi quay cảnh này. Nếu không, mọi thứ sẽ là quá sức với Monica. Nhưng sự can thiệp về kỹ xảo trong phần hậu kỳ đã làm cảnh đó trông rất thật', 'https://image.tmdb.org/t/p/w500/AdrItykbv1evqcbIPrItVWnkaKj.jpg', 'https://image.tmdb.org/t/p/w1280/xV1EfNSEg6id6juJPr1vM6p9x5X.jpg', NULL, '2002-05-22', NULL, NULL, NULL, NULL, NULL, 7.19, 3288, 30.987, 8.6, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(111, 1061474, 'Superman', 'Superman', 'superman-2025', NULL, 'Superman cố gắng can thiệp vào một cuộc khủng hoảng toàn cầu do Lex Luthor gây ra, nhưng lại bị công chúng hiểu lầm. Mọi chuyện trở nên nghiêm trọng hơn khi Luthor tạo ra một bản sao đen tối của Superman – Ultraman. Với sự giúp đỡ của Lois Lane và chú chó siêu năng lực Krypto, Superman phải đối mặt với chính bản ngã của mình để giành lại niềm tin từ nhân loại.', 'https://image.tmdb.org/t/p/w500/f4hJ5yVSiOSnW9S6vtoGlNYvW5J.jpg', 'https://image.tmdb.org/t/p/w1280/eU7IfdWq8KQy0oNd4kKXS0QUR08.jpg', NULL, '2025-07-09', NULL, NULL, NULL, NULL, NULL, 7.34, 4772, 28.523, 8.7, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(112, 1083381, 'Hậu Phòng Vô Tận', 'Backrooms', 'hau-phong-vo-tan-2026', NULL, 'Một cánh cửa kỳ lạ bất ngờ xuất hiện trong tầng hầm của một cửa hàng trưng bày nội thất, mở ra lối vào một không gian bí ẩn và đáng sợ vượt ngoài mọi hiểu biết.', 'https://image.tmdb.org/t/p/w500/vpkNMkbisv5cTaIfCzUduYzXnjb.jpg', 'https://image.tmdb.org/t/p/w1280/mCpwRayjXMFzKHbjbzc5JRKfq1O.jpg', NULL, '2026-05-27', NULL, NULL, NULL, NULL, NULL, 9.20, 4, 38.012, 5.5, 9, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(113, 1159831, 'Cô Dâu!', 'The Bride!', 'co-dau-2026', NULL, 'Một cách tiếp cận táo bạo, phá vỡ mọi khuôn mẫu đối với một trong những câu chuyện hấp dẫn nhất thế giới. Bộ phim theo chân Frankenstein cô đơn (do Chrisitian Bale thủ vai) lên đường đến Chicago những năm 1930 để tìm đến nhà khoa học Dr. Euphronious (Annette Bening – 5 lần đề cử Oscar thủ vai), với hy vọng bà có thể tạo ra một người bạn đồng hành cho mình. Cả hai hồi sinh một cô gái trẻ đã bị sát hại, và Cô Dâu (Buckley thủ vai) đã ra đời. Những gì xảy ra sau đó đã vượt xa mọi tưởng tượng của họ: những vụ giết người, sự chiếm hữu, một phong trào văn hóa hoang dại và cấp tiến cũng như mối tình ngoài vòng pháp luật đầy cuồng nhiệt và bùng nổ!', 'https://image.tmdb.org/t/p/w500/60PGmrPEUId7KJQb17AAMsItMMJ.jpg', 'https://image.tmdb.org/t/p/w1280/l8rKKMU2M9dDULO9CEtDNdWAEUJ.jpg', NULL, '2026-03-04', NULL, NULL, NULL, NULL, NULL, 6.21, 461, 28.992, 9.8, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(114, 10138, 'Người Sắt 2', 'Iron Man 2', 'nguoi-sat-2-2010', NULL, 'Tony Stark tự hé lộ thân phận Người sắt của mình cho công chúng và chìm trong hào quang danh vọng. Một kẻ lạ mặt xuất hiện tấn công anh trên đường đua Monte Carlo. Tony bị hiện tượng nhiễm trùng máu đe dọa mạng sống, còn tên sát thủ kia bắt tay với đối thủ của tập đoàn Stark hòng thôn tính Tony.  Phần 2 của Người sắt là lần đầu tiên trợ thủ Warmachine xuất hiện. Phim cũng tiết lộ những bí mật về cha của Tony, Howard Stark, trước khi dẫn dắt câu chuyện sang nhân vật Captain America, đồng đội tương lai của Người sắt tại tổ chức SHIELD.', 'https://image.tmdb.org/t/p/w500/q9L8fMYW4dBQOdDAfbbxte7gciJ.jpg', 'https://image.tmdb.org/t/p/w1280/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', NULL, '2010-04-28', NULL, NULL, NULL, NULL, NULL, 6.85, 22360, 30.951, 5.8, 6, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(115, 11013, 'Nữ Thư Ký', 'Secretary', 'nu-thu-ky-2002', NULL, 'Nữ Thư Ký xoay quanh mối quan hệ tình ái đầy nhục dục giữa cô nàng thư ký xinh đẹp tên là Lee Holloway (Maggie Gyllenhaal) và ông chủ của mình, luật sư E. Edward Grey (James Spader đóng). Holloway vốn là một người phụ nữ mong manh sống tình cảm, gần đây cô được trả về từ một bệnh viện về thần kinh, và sau đó cô đã lên kế hoạch đi học để đạt được kỹ năng của một thư ký mà sau đó là cô có thể tìm được việc làm.', 'https://image.tmdb.org/t/p/w500/mdRXSE7ho185SZlXj0JSwuecEd3.jpg', 'https://image.tmdb.org/t/p/w1280/ifHgVh5c7B3mbq5CfkzwsyMRmpG.jpg', NULL, '2002-09-20', NULL, NULL, NULL, NULL, NULL, 6.80, 1909, 28.674, 8.5, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(116, 1510745, 'Ống Kính Ma Quái', 'Bodycam', 'ong-kinh-ma-quai-2026', NULL, 'Một cuộc gọi tưởng như bình thường dẫn hai sĩ quan cảnh sát đến một ngôi nhà yên ắng trong khu ngoại ô. Chỉ vài phút sau, không khí im lặng ấy vỡ tan bởi tiếng súng, và sai lầm khủng khiếp xảy ra — một người đàn ông cùng đứa con sơ sinh bị bắn chết ngay trước ống kính bodycam. Từ khoảnh khắc đó, mọi thứ trượt ra khỏi tầm kiểm soát. Những hình ảnh ghi lại dường như không chỉ đơn thuần là bằng chứng, mà còn mở ra một cánh cửa dẫn đến thứ gì đó vượt ngoài lý trí. Khi tội lỗi, sợ hãi và bóng tối dần nuốt chửng họ, các sĩ quan buộc phải đối mặt với câu hỏi: liệu có thứ gì đang ẩn nấp sau những thước phim, hay chính họ mới là người bị săn đuổi?', 'https://image.tmdb.org/t/p/w500/xFpBNcG3Dlr8mYF5Kz9Tizs3Pxn.jpg', 'https://image.tmdb.org/t/p/w1280/qmWypRw88VYp35oTQn0a1sqdZRs.jpg', NULL, '2026-03-12', NULL, NULL, NULL, NULL, NULL, 5.62, 56, 25.933, 6.8, 4, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(117, 550, 'Sàn Đấu Sinh Tử', 'Fight Club', 'san-dau-sinh-tu-1999', NULL, 'Cuộc gặp gỡ định mệnh của một nhân viên giám định bảo hiểm và một gã lông bông bán xà phòng trên chuyến bay đã mở ra một cuộc phiêu lưu kỳ lạ. Với các \"câu lạc bộ chiến đấu\" ngầm hình thành ở mọi thị trấn, cuốn theo nhiều diễn biến phức tạp và một cái kết đầy kịch tính.', 'https://image.tmdb.org/t/p/w500/wBxkCbNI8eDRRfUEl8w0G2rfLyu.jpg', 'https://image.tmdb.org/t/p/w1280/xRyINp9KfMLVjRiO5nCsoRDdvvF.jpg', NULL, '1999-10-15', NULL, NULL, NULL, NULL, NULL, 8.44, 32031, 30.197, 8.0, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(118, 1290417, 'Cá Mập Săn Người', 'Thrash', 'ca-map-san-nguoi-2026', NULL, 'Dòng nước lũ dữ dội nhuộm đỏ máu khi cư dân mắc kẹt ở thị trấn ven biển chiến đấu để sinh tồn trước cơn siêu bão tàn khốc và bầy cá mập đói khát theo bão kéo đến.', 'https://image.tmdb.org/t/p/w500/adk8weka3O5648g3de4z3y4aE7G.jpg', 'https://image.tmdb.org/t/p/w1280/hniERZojXCEc7Fp3yljZUigOAhm.jpg', NULL, '2026-04-10', NULL, NULL, NULL, NULL, NULL, 6.02, 597, 27.750, 8.9, 1, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL),
(119, 372058, 'Tên Cậu Là Gì?', '君の名は。', 'ten-cau-la-gi-2016', NULL, 'Bộ phim là câu chuyện hoán đổi cơ thể của 2 cô cậu Mitsuha - nữ sinh trung học sống ở một thị trấn nhỏ của vùng Itomori và Taki – nam sinh tại thủ đô Tokyo đầy sôi động. Mitsuha luôn chán chường với cuộc sống tẻ nhạt của mình và mơ ước được làm anh chàng đẹp trai sống tại thủ đô. Trong khi đó, Taki hằng đêm lại nhìn thấy mình trong hình hài cô gái vùng miền quê. Ước mơ của cả 2 đã thành sự thật khi sao chổi nghìn năm xuất hiện trên trái đất và rồi cứ cách ngày lại được hoán đổi cơ thể cho nhau.', 'https://image.tmdb.org/t/p/w500/yV8ARrvpWaWd509QM4LwMScNDvZ.jpg', 'https://image.tmdb.org/t/p/w1280/8x9iKH8kWA0zdkgNdpAew7OstYe.jpg', NULL, '2016-08-26', NULL, NULL, NULL, NULL, NULL, 8.48, 12553, 28.234, 8.3, 8, 0, 1, 'active', 0, 0, NULL, '2026-05-26 10:30:53', '2026-05-26 10:31:00', NULL);
