(2, 46, 1, 'App\\Models\\Review', 'Spoiler không cảnh báo', 'Review này tiết lộ toàn bộ cái kết của phim nhưng không hề check vào ô Spoiler. Làm hỏng trải nghiệm người chưa xem.', 0, 'pending', '2026-05-26 10:31:10', '2026-05-26 10:31:10'),
(3, 25, 474, 'App\\Models\\Review', 'Công kích cá nhân', 'Reviewer này đang chửi rủa những người khen phim này, gây war trong cộng đồng.', 0, 'pending', '2026-05-26 10:31:10', '2026-05-26 10:31:10');
INSERT INTO `reviews` (`id`, `user_id`, `movie_id`, `tv_show_id`, `title`, `slug`, `thumbnail`, `excerpt`, `content`, `rating`, `is_spoiler`, `status`, `published_at`, `view_count`, `likes_count`, `comments_count`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 9, 1, NULL, 'Xem giải trí cũng ổn', 'xem-giai-tri-cung-on', NULL, 'Ý tưởng ban đầu rất thú vị nhưng cách triển khai chưa tới. Có quá nhiều tuyến nhân vật phụ thừa thãi...', 'Ý tưởng ban đầu rất thú vị nhưng cách triển khai chưa tới. Có quá nhiều tuyến nhân vật phụ thừa thãi không đóng góp gì cho mạch truyện chính. Diễn xuất của nữ chính đôi chỗ còn hơi gượng gạo, thiếu cảm xúc.', 7.2, 0, 'published', '2026-03-23 20:01:54', 374, 0, 0, '2026-05-26 10:30:54', '2026-05-26 10:30:54', NULL),
(2, 38, 2, NULL, 'Đáng thất vọng', 'dang-that-vong', NULL, 'Phim cố gắng nhồi nhét quá nhiều thông điệp triết lý nhưng lại thành ra sáo rỗng và khô khan. Dài gầ...', 'Phim cố gắng nhồi nhét quá nhiều thông điệp triết lý nhưng lại thành ra sáo rỗng và khô khan. Dài gần 2 tiếng rưỡi mà nội dung chỉ tóm gọn lại được trong 10 phút. Rất buồn ngủ, mình đã thấy nhiều người bỏ về giữa chừng.', 4.2, 0, 'published', '2026-04-30 14:45:54', 200, 0, 0, '2026-05-26 10:30:54', '2026-05-26 10:30:54', NULL),
(3, 17, 3, NULL, 'Giải trí chất lượng', 'giai-tri-chat-luong', NULL, 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn...', 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn phản diện. Màu phim đẹp, nhạc phim hay. Điểm trừ duy nhất là cái kết hơi vội.', 8.8, 0, 'published', '2026-05-11 04:26:54', 501, 0, 4, '2026-05-26 10:30:54', '2026-05-26 10:31:01', NULL),
(4, 22, 4, NULL, NULL, 'review-1779791454', NULL, 'Hình ảnh và kỹ xảo được đầu tư hoành tráng nhưng cốt truyện lại quá mỏng. Lời thoại đôi khi bị sến v...', 'Hình ảnh và kỹ xảo được đầu tư hoành tráng nhưng cốt truyện lại quá mỏng. Lời thoại đôi khi bị sến và kịch. Nếu bạn chỉ cần xem cảnh hành động cháy nổ thì phim này đáp ứng được, còn mong đợi chiều sâu thì không.', 6.4, 0, 'published', '2026-04-06 22:37:54', 153, 0, 0, '2026-05-26 10:30:54', '2026-05-26 10:30:54', NULL),
(5, 11, 5, NULL, 'Trải nghiệm tuyệt vời', 'trai-nghiem-tuyet-voi', NULL, 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn...', 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn phản diện. Màu phim đẹp, nhạc phim hay. Điểm trừ duy nhất là cái kết hơi vội.', 8.8, 1, 'published', '2026-05-06 17:31:54', 87, 0, 4, '2026-05-26 10:30:54', '2026-05-26 10:31:01', NULL),
(6, 7, 6, NULL, 'Kịch bản cuốn hút', 'kich-ban-cuon-hut', NULL, 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn...', 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn phản diện. Màu phim đẹp, nhạc phim hay. Điểm trừ duy nhất là cái kết hơi vội.', 8.3, 0, 'published', '2026-04-29 01:45:54', 190, 0, 4, '2026-05-26 10:30:54', '2026-05-26 10:31:01', NULL),
(7, 32, 7, NULL, 'Siêu phẩm của năm', 'sieu-pham-cua-nam', NULL, 'Kịch bản quá xuất sắc, lồng ghép nhiều tầng ý nghĩa mà phải suy ngẫm mãi mới hiểu hết được. Đạo diễn...', 'Kịch bản quá xuất sắc, lồng ghép nhiều tầng ý nghĩa mà phải suy ngẫm mãi mới hiểu hết được. Đạo diễn đã làm rất tốt việc dẫn dắt cảm xúc người xem từ tò mò đến vỡ òa ở những phút cuối cùng. Chắc chắn sẽ xem lại.', 9.9, 0, 'published', '2026-04-25 05:19:54', 983, 0, 0, '2026-05-26 10:30:54', '2026-05-26 10:30:54', NULL),
