(482, 7, NULL, 36, 'Kịch bản quá lỏng lẻo', 'kich-ban-qua-long-leo-6', NULL, 'Thật sự thất vọng so với những gì trailer hứa hẹn. Nhịp phim rời rạc, chuyển cảnh lộn xộn khiến mình...', 'Thật sự thất vọng so với những gì trailer hứa hẹn. Nhịp phim rời rạc, chuyển cảnh lộn xộn khiến mình đôi lúc không hiểu chuyện gì đang xảy ra. Phí cả một dàn cast thực lực cho một kịch bản chắp vá như thế này.', 4.8, 0, 'published', '2026-05-16 20:32:57', 63, 0, 0, '2026-05-26 10:30:57', '2026-05-26 10:30:57', NULL),
(483, 32, 105, NULL, 'Giải trí chất lượng', 'giai-tri-chat-luong-43', NULL, 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn...', 'Phim làm tốt việc xây dựng tâm lý nhân vật, khiến khán giả có thể đồng cảm với cả nhân vật chính lẫn phản diện. Màu phim đẹp, nhạc phim hay. Điểm trừ duy nhất là cái kết hơi vội.', 8.3, 0, 'published', '2026-02-07 16:49:57', 924, 0, 0, '2026-05-26 10:30:57', '2026-05-26 10:30:57', NULL),
(484, 24, 114, NULL, 'Không thể xuất sắc hơn', 'khong-the-xuat-sac-hon-14', NULL, 'Một kiệt tác thực sự của điện ảnh. Mọi thứ từ góc máy, ánh sáng, âm nhạc đến diễn xuất đều hoàn hảo...', 'Một kiệt tác thực sự của điện ảnh. Mọi thứ từ góc máy, ánh sáng, âm nhạc đến diễn xuất đều hoàn hảo đến mức khó tin. Mình đã xem đi xem lại nhiều lần mà vẫn thấy nổi da gà ở những phân cảnh cao trào.', 9.7, 0, 'published', '2026-01-01 23:31:57', 543, 0, 2, '2026-05-26 10:30:57', '2026-05-26 10:31:04', NULL),
